const CURRENT_USER_KEY = 'current_user';

// 【安全加固】全局 fetch 包装：自动为同源 /api/ 请求附带登录 token。
// 保证后端鉴权生效后，前端所有请求（含现有几十处未显式带头的 fetch）都能通过校验。
(function () {
  if (window.__authFetchPatched) return;
  window.__authFetchPatched = true;
  const origFetch = window.fetch.bind(window);
  // 会话过期处理：仅提示一次，避免并发请求弹多个框
  window.__sessionExpiredShown = false;
  function handleSessionExpired() {
    if (window.__sessionExpiredShown) return;
    window.__sessionExpiredShown = true;
    try {
      sessionStorage.removeItem(LOGIN_TOKEN_KEY);
      sessionStorage.removeItem(CURRENT_USER_KEY);
      alert('登录已过期，请重新登录');
      window.location.hash = '';
      if (typeof window.showLoginPage === 'function') window.showLoginPage();
      else window.location.reload();
    } catch (e) { /* ignore */ }
  }
  window.fetch = function (input, init) {
    init = init || {};
    try {
      const url = typeof input === 'string' ? input : (input && input.url) || '';
      if (/^\/(api\/|api$)/.test(url) && !/^http/i.test(url)) {
        const headers = new Headers(init.headers || {});
        const token = sessionStorage.getItem(LOGIN_TOKEN_KEY);
        if (token && token !== 'null' && token !== 'undefined' && !headers.has('Authorization')) {
          headers.set('Authorization', token);
        }
        init.headers = headers;
      }
    } catch (e) { /* ignore */ }
    return origFetch(input, init).then(function (res) {
      try {
        // 受保护接口返回 401 = 会话过期/未登录，统一提示并跳转登录
        if (res.status === 401) {
          const u = typeof input === 'string' ? input : (input && input.url) || '';
          if (/^\/(api\/(?!login|auth\/check|logout))/i.test(u)) {
            handleSessionExpired();
          }
        }
      } catch (e2) { /* ignore */ }
      return res;
    });
  };
})();

// 【日志开关】生产模式静默 console.log/debug 调试日志，避免刷屏与信息泄露；URL 加 ?debug=1 可临时开启调试日志。
// 保留 console.error/warn，方便排查错误而不会被大量调试输出淹没。
(function () {
  const debugOn = /[?&]debug=1/.test(window.location.search || '');
  window.__ENABLE_DEBUG__ = debugOn;
  if (!debugOn) {
    for (const m of ['log', 'debug']) {
      try { window.console[m] = function () {}; } catch (e) {}
    }
  }
})();

