// 检查登录状态
function isLoggedIn() {
  const token = sessionStorage.getItem(LOGIN_TOKEN_KEY);
  return token && token !== 'null' && token !== 'undefined';
}

// 获取当前用户
function getCurrentUser() {
  return currentUser;
}

// 保存登录状态
function saveLogin(token, user) {
  sessionStorage.setItem(LOGIN_TOKEN_KEY, token);
  sessionStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
  currentUser = user;
}

// 清除登录状态
function clearLogin() {
  sessionStorage.removeItem(LOGIN_TOKEN_KEY);
  sessionStorage.removeItem(CURRENT_USER_KEY);
  currentUser = null;
}

// ==================== 角色细分权限控制 ====================
// 设计原则：管理员/超级管理员拥有全部权限；
// 普通角色仅在「角色管理」里配置了权限(permissions 非空)后才做细分控制；
// 权限为空或未能匹配角色的用户，视为全权限（兜底，避免破坏现有工作流）。
function isAdminUser() {
  const u = currentUser || JSON.parse(sessionStorage.getItem(CURRENT_USER_KEY) || '{}');
  if (!u || !u.role) return true;
  if (u.username === 'admin') return true;
  const r = String(u.role || '');
  return r.includes('管理员') || r.includes('系统管理员') || r.includes('超级管理员');
}

// 返回当前用户角色的权限数组；返回 null 表示"拥有全部权限"（管理员或未配置）。
function getRolePermissions() {
  if (isAdminUser()) return null;
  if (!data || !Array.isArray(data.roles)) return null;
  const u = currentUser || JSON.parse(sessionStorage.getItem(CURRENT_USER_KEY) || '{}');
  const role = data.roles.find(x => String(x.name) === String(u.role));
  if (!role) return null;
  const perms = role.permissions;
  if (!Array.isArray(perms) || perms.length === 0) return null;
  return perms;
}

// 是否拥有某个一级模块的访问权（该模块下有任一权限即视为可进入）
function hasModuleAccess(module) {
  const perms = getRolePermissions();
  return PERMCORE.hasModuleAccess(perms, module);
}

// 是否拥有 模块-功能[-动作] 权限；action 省略时只需该功能下任一权限
function hasPerm(module, item, action) {
  const perms = getRolePermissions();
  return PERMCORE.hasPerm(perms, module, item, action);
}

// data-perm 属性：形如 "销售管理-待审核订单-审核"（2段时按"查看"判定）
function checkPermSpec(spec) {
  const perms = getRolePermissions();
  return PERMCORE.checkPermSpec(perms, spec);
}

