// 按二级功能权限隐藏菜单项：无该功能任何权限的项隐藏
function filterSubmenuPermissions() {
  for (const moduleName of Object.keys(SUBMENU_ITEM_MAP)) {
    const dropdownId = Object.keys(MENU_MODULE_MAP).find(id => MENU_MODULE_MAP[id] === moduleName);
    const box = dropdownId && document.getElementById(dropdownId);
    if (!box) continue;
    const groups = SUBMENU_ITEM_MAP[moduleName];
    // 文本→功能 反查
    const itemToFeature = {};
    for (const feature of Object.keys(groups)) {
      (groups[feature] || []).forEach(t => { itemToFeature[t] = feature; });
    }
    box.querySelectorAll('.sidebar-dropdown-content-item').forEach(item => {
      const text = (item.textContent || '').trim();
      const feature = itemToFeature[text];
      if (!feature) return; // 未配置映射的菜单项跟随模块显示
      item.classList.toggle('perm-hidden', !hasPerm(moduleName, feature));
    });
  }
}

// 角色分级：管理员显示"系统管理"菜单，其余角色隐藏（配合后端 requireAdmin/requireAuth 双重管控）
function applyRoleGating() {
  document.body.classList.toggle('no-admin', !isAdminUser());
  applyMenuPermissions();
  startPermObserver();
}

// 动态渲染的按钮/菜单项（带 data-perm）无法在初始时过滤，
// 借助 MutationObserver 在新增节点后统一按权限隐藏/显示。
let _permObserverStarted = false;
function startPermObserver() {
  if (_permObserverStarted || typeof MutationObserver === 'undefined') return;
  _permObserverStarted = true;
  const filter = () => document.querySelectorAll('[data-perm]').forEach(btn =>
    btn.classList.toggle('perm-hidden', !checkPermSpec(btn.getAttribute('data-perm'))));
  const mo = new MutationObserver(muts => {
    for (const m of muts) {
      if (m.type !== 'childList' || !m.addedNodes || m.addedNodes.length === 0) continue;
      let needFilter = false;
      for (const n of m.addedNodes) {
        if (n.nodeType !== 1) continue;
        if (n.hasAttribute && n.hasAttribute('data-perm')) { needFilter = true; break; }
        if (n.querySelector && n.querySelector('[data-perm]')) { needFilter = true; break; }
      }
      if (needFilter) { filter(); return; }
    }
  });
  mo.observe(document.body, { childList: true, subtree: true });
}

// HTML 转义：渲染用户可控文本进 innerHTML 前调用，防止存储型 XSS
function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// 数据导出：调用后端 /api/export/:collection 生成 CSV 并触发浏览器下载
async function downloadCSV(collection, filename) {
  try {
    const token = sessionStorage.getItem(LOGIN_TOKEN_KEY);
    const res = await fetch('/api/export/' + collection, { headers: { 'Authorization': token || '' } });
    if (!res.ok) {
      const j = await res.json().catch(() => ({}));
      showAlertModal('导出失败', j.message || '服务器返回错误');
      return;
    }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = (filename || collection + '_' + new Date().toISOString().slice(0, 10)) + '.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  } catch (e) {
    showAlertModal('导出失败', e.message || '导出出现异常');
  }
}

// 处理退出登录
async function handleLogout() {
  try {
    const token = sessionStorage.getItem(LOGIN_TOKEN_KEY);
    const response = await fetch('/api/logout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': token || '' }
    });
    
    await response.json();
  } catch (e) {
    console.error('退出登录失败:', e);
  }
  
  clearLogin();
  window.location.href = '/login';
}

