function showInputModal(title, message, defaultValue = '', placeholder = '') {
  return new Promise((resolve) => {
    const modalHtml = `
      <div id="inputModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
        <div class="bg-white rounded-xl w-96 shadow-xl overflow-hidden animate-fade-in">
          <div class="bg-gradient-to-r from-indigo-500 to-indigo-600 px-6 py-4">
            <h3 class="text-lg font-semibold text-white text-center">${title || '输入'}</h3>
          </div>
          <div class="p-6">
            <p class="text-slate-600 text-sm mb-4">${message}</p>
            <input type="text" id="modalInputValue" class="w-full px-4 py-3 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-teal-500 text-sm" 
                   value="${defaultValue || ''}" placeholder="${placeholder || ''}" autofocus>
          </div>
          <div class="px-6 py-4 bg-slate-50 flex justify-end gap-3">
            <button onclick="closeInputModal(null)" class="px-6 py-2 border border-slate-300 text-slate-600 rounded-lg hover:bg-slate-100 transition-colors text-sm">取消</button>
            <button onclick="submitInputModal()" class="px-6 py-2 bg-gradient-to-r from-indigo-500 to-indigo-600 text-white rounded-lg hover:from-indigo-600 hover:to-indigo-700 transition-all shadow-md hover:shadow-lg text-sm">确定</button>
          </div>
        </div>
      </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    
    window.submitInputModal = function() {
      const input = document.getElementById('modalInputValue');
      const value = input ? input.value.trim() : '';
      closeInputModal(value);
    };
    
    window.closeInputModal = function(value) {
      const modal = document.getElementById('inputModal');
      if (modal) modal.remove();
      resolve(value || null);
    };
  });
}

function closeInputModal() {
  const modal = document.getElementById('inputModal');
  if (modal) modal.remove();
}

