function filterDataSourceItems() {
  const searchText = document.getElementById('ds-search-input').value.toLowerCase();
  const itemsContainer = document.getElementById('ds-items-container');
  const labels = itemsContainer.querySelectorAll('label');
  
  labels.forEach(label => {
    const text = label.querySelector('span').textContent.toLowerCase();
    if (text.includes(searchText)) {
      label.style.display = 'flex';
    } else {
      label.style.display = 'none';
    }
  });
}

function showAddDataSourceItemModal() {
  const modal = document.getElementById('modal');
  const modalContent = document.getElementById('modal-content');
  
  modalContent.innerHTML = `
    <div class="p-6">
      <h3 class="text-lg font-semibold text-slate-800 mb-4">新增显示值</h3>
      
      <div class="mb-4">
        <label class="block text-sm font-medium text-slate-700 mb-2">显示值</label>
        <input type="text" id="new-ds-item-value" class="w-full px-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500" placeholder="请输入显示值">
      </div>
      
      <div class="flex justify-end gap-3">
        <button type="button" onclick="showDataSourceSelector(currentDataSourceField, currentDataSourceKey, '')" class="px-4 py-2 border border-slate-300 rounded hover:bg-slate-50">取消</button>
        <button type="button" onclick="addItemFromSelectorModal()" class="px-4 py-2 bg-teal-500 text-white rounded hover:bg-teal-600">确认添加</button>
      </div>
    </div>
  `;
}

function addItemFromSelectorModal() {
  const newValue = document.getElementById('new-ds-item-value').value.trim();
  
  if (!newValue) {
    showAlertModal('提示', '请输入显示值');
    return;
  }
  
  if (!dataSources[currentDataSourceKey]) {
    dataSources[currentDataSourceKey] = [];
  }
  
  const existingItems = dataSources[currentDataSourceKey];
  const isDuplicate = existingItems.some(item => item.displayValue === newValue);
  
  if (isDuplicate) {
    showAlertModal('提示', '该显示值已存在');
    return;
  }
  
  const newItem = {
    id: Date.now(),
    displayValue: newValue,
    order: existingItems.length + 1,
    isDefault: false
  };
  
  existingItems.push(newItem);
  saveDataSources();
  
  showDataSourceSelector(currentDataSourceField, currentDataSourceKey, '');
}

let isConfirming = false;

function confirmDataSourceSelection() {
  if (isConfirming) {
    // console.log('confirmDataSourceSelection already in progress, skipping');
    return;
  }
  
  isConfirming = true;
  // console.log('confirmDataSourceSelection called');
  // console.log('currentDataSourceField:', currentDataSourceField);
  
  try {
    const checkboxes = document.querySelectorAll('.ds-checkbox:checked');
    // console.log('checkboxes found:', checkboxes.length);
    
    const selectedValues = Array.from(checkboxes).map(cb => cb.value);
    // console.log('selectedValues:', selectedValues);
    
    const result = selectedValues.join(',');
    // console.log('result:', result);
    
    const field = document.getElementById(currentDataSourceField);
    // console.log('field element:', field);
    
    if (field) {
      field.value = result;
      // console.log('field value set to:', field.value);
      
      // 更新按钮显示
      let button = field.nextElementSibling;
      // 如果下一个元素不是按钮，继续
      while (button && button.tagName !== 'BUTTON') {
        button = button.nextElementSibling;
      }
      
      if (button && button.tagName === 'BUTTON') {
        // console.log('Updating button text');
        button.textContent = result || '选择';
        button.classList.remove('bg-teal-500', 'text-white');
        button.classList.add('bg-white', 'border', 'border-slate-300', 'text-slate-700');
      }
    }
    
    closeModal();
    
    if (currentDataSourceField === 'product-spec') {
      updateQuickSpecPricesFromSelection();
    }
  } catch (e) {
    console.error('Error in confirmDataSourceSelection:', e);
  } finally {
    setTimeout(() => {
      isConfirming = false;
    }, 300);
  }
}

