let quickSpecPrices = [];

function updateQuickSpecPricesFromSelection() {
  const specValue = document.getElementById('product-spec').value;
  const defaultFactoryPrice = parseFloat(document.getElementById('factory-price').value) || 0;
  const defaultCostPrice = parseFloat(document.getElementById('cost-price').value) || 0;
  const defaultShowroomPrice = parseFloat(document.getElementById('showroom-price').value) || 0;
  
  const tbody = document.getElementById('quick-spec-price-tbody');
  if (!tbody) return;
  
  if (!specValue) {
    quickSpecPrices = [];
    tbody.innerHTML = `
      <tr>
        <td colspan="4" class="px-4 py-8 text-center text-slate-500 text-sm">请在"规格"字段选择多个规格后自动显示</td>
      </tr>
    `;
    return;
  }
  
  const specs = specValue.split(',').map(s => s.trim()).filter(s => s);
  
  if (specs.length <= 1) {
    quickSpecPrices = [];
    tbody.innerHTML = `
      <tr>
        <td colspan="4" class="px-4 py-8 text-center text-slate-500 text-sm">选择一个规格时使用产品信息中的价格</td>
      </tr>
    `;
    return;
  }
  
  quickSpecPrices = specs.map(spec => {
    const existing = quickSpecPrices.find(p => p.spec === spec);
    if (existing) {
      return existing;
    }
    return {
      spec: spec,
      factoryPrice: defaultFactoryPrice,
      costPrice: defaultCostPrice,
      showroomPrice: defaultShowroomPrice
    };
  });
  
  renderQuickSpecPrices();
}

function renderQuickSpecPrices() {
  const tbody = document.getElementById('quick-spec-price-tbody');
  if (!tbody) return;
  
  tbody.innerHTML = quickSpecPrices.map((item, index) => `
    <tr class="hover:bg-slate-50 transition-colors">
      <td class="px-5 py-4 text-sm text-slate-700 font-medium">${item.spec}</td>
      <td class="px-5 py-4">
        <div class="relative">
          <span class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">¥</span>
          <input type="number" class="w-full pl-8 pr-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-teal-500 transition-all text-sm" value="${item.factoryPrice}" onchange="updateSpecPrice(${index}, 'factoryPrice', parseFloat(this.value))" placeholder="0.00" step="0.01">
        </div>
      </td>
      <td class="px-5 py-4">
        <div class="relative">
          <span class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">¥</span>
          <input type="number" class="w-full pl-8 pr-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-teal-500 transition-all text-sm" value="${item.costPrice}" onchange="updateSpecPrice(${index}, 'costPrice', parseFloat(this.value))" placeholder="0.00" step="0.01">
        </div>
      </td>
      <td class="px-5 py-4">
        <div class="relative">
          <span class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">¥</span>
          <input type="number" class="w-full pl-8 pr-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-teal-500 transition-all text-sm" value="${item.showroomPrice}" onchange="updateSpecPrice(${index}, 'showroomPrice', parseFloat(this.value))" placeholder="0.00" step="0.01">
        </div>
      </td>
    </tr>
  `).join('');
}

function updateSpecPrice(index, field, value) {
  if (quickSpecPrices[index]) {
    quickSpecPrices[index][field] = value || 0;
  }
}

