function filterProductTypeItems() {
  const searchText = document.getElementById('pt-search-input').value.toLowerCase();
  const itemsContainer = document.getElementById('pt-items-container');
  const labels = itemsContainer.querySelectorAll('label');
  
  labels.forEach(label => {
    const text = label.querySelector('span').textContent.toLowerCase();
    if (text.includes(searchText)) {
      label.style.display = 'flex';
    } else {
      label.style.display = 'none';
    }
  });
}

