function addProductTypeItem() {
  const newValue = document.getElementById('new-pt-item-value').value.trim();
  
  if (!newValue) {
    showAlertModal('提示', '请输入产品类型');
    return;
  }
  
  const isDuplicate = productTypeData.some(item => item.displayValue === newValue);
  
  if (isDuplicate) {
    showAlertModal('提示', '该产品类型已存在');
    return;
  }
  
  const newItem = {
    id: Date.now(),
    displayValue: newValue,
    order: productTypeData.length + 1,
    productionCycle: '',
  };
  
  productTypeData.push(newItem);
  saveProductTypeData();
  
  showProductTypeSelector();
}

function confirmProductTypeSelection() {
  const checkboxes = document.querySelectorAll('.pt-checkbox:checked');
  const selectedValues = Array.from(checkboxes).map(cb => cb.value);
  const result = selectedValues.join(',');
  
  document.getElementById('product-type').value = result;
  closeModal();
}

