// 清理旧的、不需要的数据源（只执行一次）
function cleanupDataSources() {
  const CLEANUP_FLAG_KEY = 'dataSourcesCleaned';
  
  // 检查是否已经清理过
  if (!localStorage.getItem(CLEANUP_FLAG_KEY)) {
    const neededDataSources = ['颜色', '尺寸', '台面角度', '台面颜色', '台面材质', '供应商', '单位'];
    const keys = Object.keys(dataSources);
    
    // 删除不需要的数据源
    for (const key of keys) {
      if (!neededDataSources.includes(key)) {
        delete dataSources[key];
      }
    }
    
    // 保存清理后的数据
    saveDataSources();
    
    // 标记已经清理过
    localStorage.setItem(CLEANUP_FLAG_KEY, 'true');
  }
}

