function formatCurrency(amount) {
  if (amount === null || amount === undefined || isNaN(Number(amount))) {
    return '¥0.00';
  }
  return '¥' + Number(amount).toLocaleString('zh-CN', { minimumFractionDigits: 2 });
}

function formatMultiValue(value) {
  if (!value) return '-';
  const values = value.split(',').map(v => v.trim()).filter(v => v);
  if (values.length <= 1) return value;
  return values.join('\n');
}

function getStatusClass(status) {
  const map = { 
    pending: 'status-pending', 
    approved: 'bg-teal-100 text-teal-700', 
    allocated: 'bg-cyan-100 text-cyan-700',
    in_production: 'bg-orange-100 text-orange-700',
    in_progress: 'status-in-progress', 
    shipped: 'bg-blue-100 text-blue-700', 
    completed: 'status-completed', 
    cancelled: 'status-cancelled' 
  };
  return map[status] || 'status-pending';
}

function getStatusText(status) {
  const map = { 
    pending: '待审核', 
    approved: '已审核', 
    allocated: '已配货',
    in_production: '生产中',
    in_progress: '进行中', 
    shipped: '已发货', 
    completed: '已完成', 
    cancelled: '已作废' 
  };
  return map[status] || status;
}

function getDeliveryMethodText(method) {
  if (!method) return '-';
  
  const deliveryMethods = dataSources['提货方式'] || [];
  const found = deliveryMethods.find(item => item.displayValue === method);
  if (found) {
    return found.displayValue;
  }
  
  return method;
}

function getProductName(id) {
  const product = data.products.find(p => p.id === id);
  return product ? product.name : '未知';
}

function getCustomerName(id) {
  const customer = data.customers.find(c => String(c.id) === String(id));
  return customer ? customer.name : '未知';
}

function hasEnoughStock(order) {
  if (!order || !order.items || order.items.length === 0) {
    return false;
  }
  
  for (const item of order.items) {
    const productId = item.productId || item.product_id;
    const requiredQty = Number(item.quantity) || 0;
    
    if (requiredQty <= 0) continue;
    
    const inventory = data.inventory.find(inv => String(inv.productId) === String(productId));
    const availableStock = inventory ? (Number(inventory.quantity) || 0) : 0;
    
    if (availableStock < requiredQty) {
      return false;
    }
  }
  
  return true;
}

function getVisibleCustomers() {
  const user = currentUser;
  if (!user) return data.customers;
  const isAdmin = user.role && (user.role.includes('管理员') || user.role.includes('系统管理员'));
  if (isAdmin) return data.customers;
  return data.customers.filter(customer =>
    customer.salesman === user.name ||
    customer.maintainer === user.name ||
    customer.follower === user.name ||
    customer.regionalManager === user.name
  );
}

function isOrderVisibleToCurrentUser(order) {
  const user = currentUser;
  if (!user) return true;
  const isAdmin = user.role && (user.role.includes('管理员') || user.role.includes('系统管理员'));
  if (isAdmin) return true;
  const customer = data.customers.find(c => String(c.id) === String(order.customerId || order.customer_id));
  if (!customer) return false;
  return customer.salesman === user.name ||
    customer.maintainer === user.name ||
    customer.follower === user.name ||
    customer.regionalManager === user.name;
}

function getSupplierName(id) {
  const supplier = data.suppliers.find(s => s.id === id);
  return supplier ? supplier.name : '未知';
}

async function fetchData() {
  // console.log('fetchData started - loading all data from backend database');
  try {
    const [products, inventory, customers, suppliers, salesOrders, purchaseOrders, financeRecords, users, roles, stockInRecords, planOrders, processes] = await Promise.all([
      fetch('/api/products').then(r => r.json()),
      fetch('/api/inventory').then(r => r.json()),
      fetch('/api/customers').then(r => r.json()),
      fetch('/api/suppliers').then(r => r.json()),
      fetch('/api/sales-orders').then(r => r.json()),
      fetch('/api/purchase-orders').then(r => r.json()),
      fetch('/api/finance-records').then(r => r.json()),
      fetch('/api/users').then(r => r.json()),
      fetch('/api/roles').then(r => r.json()),
      fetch('/api/stock-in-records').then(r => r.json()),
      fetch('/api/plan-orders').then(r => r.json()),
      fetch('/api/processes').then(r => r.json())
    ]);
    
    // console.log('Data loaded from backend:');
    // console.log('  - Products:', products.length);
    // console.log('  - Inventory:', inventory.length);
    // console.log('  - Customers:', customers.length);
    // console.log('  - Suppliers:', suppliers.length);
    // console.log('  - Sales Orders:', salesOrders.length);
    // console.log('  - Purchase Orders:', purchaseOrders.length);
    // console.log('  - Finance Records:', financeRecords.length);
    // console.log('  - Users:', users.length);
    // console.log('  - Roles:', roles.length);
    // console.log('  - Stock In Records:', stockInRecords.length);
    
    data = { products, inventory, customers, suppliers, salesOrders, purchaseOrders, financeRecords, users, roles, stockRecords: [], stockInRecords, planOrders, processes };
    
    // 从 localStorage 加载其他数据（planOrders 始终从后端 API 加载）
    const savedErpData = localStorage.getItem('erpData');
    if (savedErpData) {
      const savedData = JSON.parse(savedErpData);
      // 合并 localStorage 中的排产数据
      if (savedData.productionScheduling && savedData.productionScheduling.length > 0) {
        data.productionScheduling = savedData.productionScheduling;
        console.log('从 localStorage 加载了', savedData.productionScheduling.length, '个排产数据');
      }
      // 合并 localStorage 中的派工订单数据
      if (savedData.schedulingOrders && savedData.schedulingOrders.length > 0) {
        data.schedulingOrders = savedData.schedulingOrders;
        console.log('从 localStorage 加载了', savedData.schedulingOrders.length, '个派工订单');
      }
      // 角色数据从后端API加载，不再从localStorage加载
    }
    
    // 如果没有计划订单数据，初始化空数组
    if (!data.planOrders) {
      data.planOrders = [];
    }
    // 如果没有派工订单数据，初始化空数组
    if (!data.schedulingOrders) {
      data.schedulingOrders = [];
    }
    
    // // // // console.log('fetchData - products loaded:', products);
    // // // // console.log('fetchData - first product packageCount:', products[0]?.packageCount);
    // // // // console.log('fetchData - first product image:', products[0]?.image);
    // // // // console.log('fetchData - first product tabletopColor:', products[0]?.tabletopColor);
    
    const savedWarehouseData = localStorage.getItem('warehouseData');
    if (savedWarehouseData) {
      warehouseData = JSON.parse(savedWarehouseData);
    }
  } catch (error) {
    console.error('Failed to fetch data:', error);
  }
}

