function highlightSidebar(page) {
  document.querySelectorAll('.sidebar-item').forEach(item => {
    item.classList.remove('active');
    item.classList.remove('bg-cyan-50');
    item.classList.remove('border-l-3');
    item.classList.remove('border-cyan-500');
    const span = item.querySelector('span');
    if (span) {
      span.classList.remove('text-slate-700');
      span.classList.remove('text-cyan-700');
      span.classList.add('text-slate-600');
    }
    const svg = item.querySelector('svg');
    if (svg) {
      svg.classList.remove('text-cyan-500');
      svg.classList.add('text-slate-500');
    }
  });
  
  const activeItem = document.querySelector(`.sidebar-item[data-page="${page}"]`);
  if (activeItem) {
    activeItem.classList.add('active');
    activeItem.classList.add('bg-cyan-50');
    activeItem.classList.add('border-l-3');
    activeItem.classList.add('border-cyan-500');
    const span = activeItem.querySelector('span');
    if (span) {
      span.classList.add('text-slate-700');
      span.classList.remove('text-slate-600');
    }
    const svg = activeItem.querySelector('svg');
    if (svg) {
      svg.classList.add('text-cyan-500');
      svg.classList.remove('text-slate-500');
    }
  }
}

async function renderPage(page) {
  const titles = {
    dashboard: ['仪表盘', '全栈进销存管理系统 - 数据由后端提供'],
    sales: ['销售管理', '管理客户和销售订单'],
    production: ['生产管理', '管理生产计划和订单'],
    purchase: ['采购管理', '管理供应商和采购订单'],
    inventory: ['库存管理', '管理库存和出入库'],
    finance: ['财务管理', '管理财务收支记录'],
    reports: ['报表管理', '报表统计和分析'],
    notifications: ['消息与待办', '审批、库存预警、交期、采购等实时待办'],
    settings: ['系统设置', '系统配置和管理'],
    materials: ['资料管理', '基础资料管理'],
    admin: ['系统管理', '系统管理和维护']
  };
  
  document.getElementById('page-title').textContent = titles[page] ? titles[page][0] : '页面';
  document.getElementById('page-subtitle').textContent = titles[page] ? titles[page][1] : '';
  
  const container = document.getElementById('page-content');
  if (container) {
    container.innerHTML = '<div class="flex justify-center items-center py-20"><svg class="animate-spin w-8 h-8 text-teal-500" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg></div>';
  }
  
  try {
    await fetchData();
  } catch (e) {
    console.error('Failed to fetch data:', e);
  }
  
  switch(page) {
    case 'dashboard': await renderDashboard(); break;
    case 'sales': await renderSales(); break;
    case 'purchase': await renderPurchase(); break;
    case 'inventory': await renderInventory(); break;
    case 'finance': await renderFinance(); break;
    case 'production': await renderProduction(); break;
    case 'reports': await renderReports(); break;
    case 'notifications': await renderNotifications(); break;
    case 'settings': await renderSettings(); break;
    case 'materials': await renderMaterials(); break;
    case 'admin': await renderAdmin(); break;
    default: await renderDashboard();
  }
}

async function renderDashboard() {
  const dashboard = await fetch('/api/dashboard').then(r => r.json());
  // 加载智能预警与采购建议
  let alerts = { count: 0, alerts: [] };
  let purchaseSuggestions = { count: 0, suggestions: [] };
  let dispatchSuggestions = { recommended: '', workload: [] };
  try {
    alerts = await fetch('/api/alerts').then(r => r.json());
  } catch (e) { console.error('加载预警失败:', e); }
  try {
    purchaseSuggestions = await fetch('/api/purchase-suggestions').then(r => r.json());
  } catch (e) { console.error('加载采购建议失败:', e); }
  try {
    dispatchSuggestions = await fetch('/api/dispatch-suggestions').then(r => r.json());
  } catch (e) { console.error('加载派工建议失败:', e); }

  const alertLevelStyle = { danger: 'border-red-200 bg-red-50', warning: 'border-amber-200 bg-amber-50', info: 'border-sky-200 bg-sky-50' };
  const alertDotStyle = { danger: 'bg-red-500', warning: 'bg-amber-500', info: 'bg-sky-500' };
  const alertTitleStyle = { danger: 'text-red-700', warning: 'text-amber-700', info: 'text-sky-700' };

  // ===== 图表辅助函数（原生 SVG，零外部依赖） =====
  // 横向条形图：近14天销售趋势
  function trendBarsHTML(trend) {
    if (!trend || !trend.length) return '<p class="text-sm text-slate-400 text-center py-6">暂无销售数据</p>';
    const max = Math.max(1, ...trend.map(t => t.amount));
    return trend.map(t => {
      const w = Math.max(2, Math.round((t.amount / max) * 100));
      const label = String(t.date || '').slice(5); // MM-DD
      return `
        <div class="flex items-center gap-2" title="${t.date} 销售额 ${formatCurrency(t.amount)}">
          <span class="w-10 text-[10px] text-slate-500 text-right flex-shrink-0">${label}</span>
          <div class="flex-1 h-3.5 bg-slate-100 rounded-sm overflow-hidden">
            <div class="h-full md:rounded-sm ${t.amount > 0 ? 'bg-gradient-to-r from-teal-400 to-teal-600' : ''}" style="width:${w}%"></div>
          </div>
          <span class="w-14 text-right text-[10px] text-slate-600 flex-shrink-0">${formatCompact(t.amount)}</span>
        </div>`;
    }).join('');
  }
  // 环形图 + 图例：订单状态分布
  function statusDonutHTML(dist) {
    const colors = { pending: '#f59e0b', approved: '#3b82f6', in_progress: '#8b5cf6', shipped: '#06b6d4', completed: '#10b981', cancelled: '#ef4444', returned: '#f97316' };
    const total = dist.reduce((s, d) => s + d.count, 0);
    if (!total) return '<p class="text-sm text-slate-400 text-center py-6">暂无订单</p>';
    let acc = 0;
    const arcs = dist.map(d => {
      const pct = d.count / total;
      const stroke = colors[d.status] || '#94a3b8';
      const dash = pct * 100;
      const rotate = acc * 100 * 3.6;
      acc += pct;
      return `<circle cx="50" cy="50" r="34" fill="none" stroke="${stroke}" stroke-width="14" stroke-dasharray="${dash} ${100-dash}" stroke-dashoffset="${25-dash/2}" transform="rotate(${rotate} 50 50)" stroke-linecap="butt"></circle>`;
    }).join('');
    const statusName = { pending: '待审核', approved: '已审核', in_progress: '生产中', shipped: '已发货', completed: '已完成', cancelled: '已取消', returned: '已退货' };
    const legends = dist.map(d => `
      <div class="flex items-center justify-between text-xs">
        <span class="flex items-center gap-1.5"><span class="w-2.5 h-2.5 rounded-sm" style="background:${colors[d.status] || '#94a3b8'}"></span>${statusName[d.status] || d.status}</span>
        <span class="text-slate-500">${d.count} <span class="text-slate-400">(${Math.round(d.count/total*100)}%)</span></span>
      </div>`).join('');
    return `<div class="flex items-center justify-center gap-6">
      <div class="w-28 h-28 relative flex-shrink-0">
        <svg viewBox="0 0 100 100" class="w-full h-full">${arcs}</svg>
        <div class="absolute inset-0 flex flex-col items-center justify-center"><span class="text-lg font-bold text-slate-800">${total}</span><span class="text-[10px] text-slate-400">订单</span></div>
      </div>
      <div class="flex-1 min-w-0 space-y-1.5">${legends}</div>
    </div>`;
  }
  // 库存品类占比：简单横条 + 百分比
  function categoryHTML(dist) {
    if (!dist || !dist.length) return '<p class="text-sm text-slate-400 text-center py-6">暂无库存数据</p>';
    const total = dist.reduce((s, d) => s + d.value, 0) || 1;
    const palette = ['#06b6d4', '#6366f1', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444', '#14b8a6', '#f97316'];
    return dist.slice(0, 8).map((d, i) => `
      <div class="flex items-center gap-2">
        <span class="w-14 text-xs text-slate-600 truncate flex-shrink-0" title="${esc(d.category)}">${esc(d.category)}</span>
        <div class="flex-1 h-4 bg-slate-100 rounded-full overflow-hidden">
          <div class="h-full rounded-full" style="width:${Math.max(2, Math.round(d.value/total*100))}%;background:${palette[i%palette.length]}"></div>
        </div>
        <span class="w-16 text-right text-xs text-slate-500 flex-shrink-0">${d.value} <span class="text-slate-400">(${Math.round(d.value/total*100)}%)</span></span>
      </div>`).join('');
  }
  // 精简金额显示
  function formatCompact(n) {
    n = Number(n) || 0;
    if (n >= 10000) return (n / 10000).toFixed(1) + 'w';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
    return String(Math.round(n));
  }
  // ===== 图表数据构造 =====
  const salesTrendArr = dashboard.salesTrend || [];
  const orderStatusArr = dashboard.orderStatusDist || [];
  const categoryArr = dashboard.categoryDist || [];
  const stockAlert = dashboard.stockAlertCount || 0;

  const alertItems = (alerts.alerts || []).slice(0, 8).map(a => `
    <div class="flex items-start gap-3 p-3 rounded-lg border ${alertLevelStyle[a.level] || alertLevelStyle.info} cursor-pointer hover:opacity-90" onclick="navigateTo('${a.target || 'dashboard'}')">
      <span class="mt-1.5 w-2 h-2 rounded-full flex-shrink-0 ${alertDotStyle[a.level] || alertDotStyle.info}"></span>
      <div class="flex-1 min-w-0">
        <p class="text-sm font-medium ${alertTitleStyle[a.level] || alertTitleStyle.info}">${a.title}${a.count ? ` (${a.count})` : ''}</p>
        <p class="text-xs text-slate-600 mt-0.5 break-all">${a.message || ''}</p>
      </div>
    </div>
  `).join('');

  const suggestionItems = (purchaseSuggestions.suggestions || []).slice(0, 5).map(s => `
    <div class="flex items-center justify-between py-2 border-b border-slate-100 last:border-0">
      <div class="min-w-0 flex-1">
        <p class="text-sm font-medium text-slate-800 truncate">${s.productName} <span class="text-xs text-slate-400 font-normal">${s.model || ''}</span></p>
        <p class="text-xs text-slate-500 mt-0.5">当前库存 ${s.current} · 待满足订单 ${s.pendingDemand} · ${s.reason}</p>
      </div>
      <div class="ml-3 text-right flex-shrink-0">
        <span class="text-sm font-bold text-teal-600">建议补 ${s.suggestedQty}</span>
      </div>
    </div>
  `).join('');

  // 智能派工建议：展示推荐执行人及各人员忙闲负载
  const workloadList = dispatchSuggestions.workload || [];
  const maxActive = Math.max(1, ...workloadList.map(w => w.active || 0));
  const dispatchItems = workloadList.length === 0
    ? '<p class="text-sm text-slate-400 text-center py-4">暂无派工数据，系统无可推荐人员</p>'
    : `
      <div class="text-sm text-slate-700 mb-3 flex items-center gap-2">
        <span class="font-medium">推荐派工给：</span>
        <span class="px-2 py-0.5 bg-indigo-100 text-indigo-700 rounded text-sm font-semibold">${dispatchSuggestions.recommended || '暂无合适人选'}</span>
        <span class="text-xs text-slate-400">（当前任务最少）</span>
      </div>
      <div class="space-y-2">
        ${workloadList.slice(0, 6).map(w => `
          <div class="flex items-center gap-3">
            <span class="w-16 text-xs text-slate-600 truncate flex-shrink-0">${esc(w.name)}</span>
            <div class="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
              <div class="h-full rounded-full ${w.active === 0 ? 'bg-teal-400' : w.active <= 1 ? 'bg-amber-400' : 'bg-red-400'}" style="width:${Math.min(100, Math.round(((w.active || 0) / maxActive) * 100))}%"></div>
            </div>
            <span class="w-24 text-right text-xs text-slate-500 flex-shrink-0">进行中 ${w.active} / 共 ${w.total}</span>
          </div>
        `).join('')}
      </div>`;

  document.getElementById('page-content').innerHTML = `
    <div class="fade-in">
      <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
        <div class="bg-white rounded-xl p-6 shadow-sm card-hover">
          <div class="flex items-center justify-between">
            <div><p class="text-sm text-slate-500 mb-1">总销售额</p><p class="text-2xl font-bold text-slate-800">${formatCurrency(dashboard.totalIncome)}</p></div>
            <div class="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center"><svg class="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"/></svg></div>
          </div>
        </div>
        <div class="bg-white rounded-xl p-6 shadow-sm card-hover">
          <div class="flex items-center justify-between">
            <div><p class="text-sm text-slate-500 mb-1">库存商品</p><p class="text-2xl font-bold text-slate-800">${dashboard.productCount}</p></div>
            <div class="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center"><svg class="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg></div>
          </div>
        </div>
        <div class="bg-white rounded-xl p-6 shadow-sm card-hover">
          <div class="flex items-center justify-between">
            <div><p class="text-sm text-slate-500 mb-1">待处理订单</p><p class="text-2xl font-bold text-slate-800">${dashboard.pendingOrders}</p></div>
            <div class="w-12 h-12 bg-yellow-100 rounded-lg flex items-center justify-center"><svg class="w-6 h-6 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg></div>
          </div>
        </div>
        <div class="bg-white rounded-xl p-6 shadow-sm card-hover">
          <div class="flex items-center justify-between">
            <div><p class="text-sm text-slate-500 mb-1">净收益</p><p class="text-2xl font-bold text-slate-800">${formatCurrency(dashboard.netProfit)}</p></div>
            <div class="w-12 h-12 bg-purple-100 rounded-lg flex items-center justify-center"><svg class="w-6 h-6 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg></div>
          </div>
        </div>
      </div>

      <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"/></svg>
              智能预警
            </h3>
            <span class="text-xs ${alerts.count > 0 ? 'text-red-500' : 'text-green-600'} font-medium">${alerts.count > 0 ? `${alerts.count} 条待处理` : '一切正常'}</span>
          </div>
          <div class="space-y-2 max-h-80 overflow-y-auto pr-1">
            ${alerts.count > 0 ? alertItems : '<p class="text-sm text-slate-400 text-center py-6">暂无预警，系统运行正常</p>'}
          </div>
        </div>

        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-teal-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
              智能采购建议
            </h3>
            <button onclick="navigateTo('purchase')" class="text-xs text-teal-600 hover:underline">去采购 →</button>
          </div>
          <div class="max-h-80 overflow-y-auto pr-1">
            ${purchaseSuggestions.count > 0 ? suggestionItems : '<p class="text-sm text-slate-400 text-center py-6">暂无采购建议，库存充足</p>'}
          </div>
        </div>
      </div>

      <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-teal-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3v18h18M8 17v-5m4 5V9m4 8v-9"/></svg>
              近 14 天销售趋势
            </h3>
          </div>
          <div class="space-y-1.5 max-h-72 overflow-y-auto pr-1">${trendBarsHTML(salesTrendArr)}</div>
        </div>
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
              订单状态分布
            </h3>
          </div>
          ${statusDonutHTML(orderStatusArr)}
        </div>
      </div>

      <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
              库存品类占比
            </h3>
          </div>
          <div class="space-y-2.5">${categoryHTML(categoryArr)}</div>
        </div>
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <div class="flex items-center justify-between mb-4">
            <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <svg class="w-5 h-5 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M12 3a9 9 0 100 18 9 9 0 000-18z"/></svg>
              库存预警
            </h3>
            <span class="text-xs ${stockAlert > 0 ? 'text-red-500' : 'text-green-600'} font-medium">${stockAlert > 0 ? `${stockAlert} 项需关注` : '库存充足'}</span>
          </div>
          <div class="grid grid-cols-2 gap-4">
            <div class="bg-red-50 rounded-lg p-4 text-center">
              <p class="text-2xl font-bold text-red-500">${dashboard.lowStock || 0}</p>
              <p class="text-xs text-slate-500 mt-1">低于安全库存</p>
            </div>
            <div class="bg-amber-50 rounded-lg p-4 text-center">
              <p class="text-2xl font-bold text-amber-500">${dashboard.outOfStock || 0}</p>
              <p class="text-xs text-slate-500 mt-1">已缺货</p>
            </div>
          </div>
          <p class="text-xs text-slate-400 mt-4">去 <button onclick="navigateTo('inventory')" class="text-teal-600 hover:underline">库存管理 →</button> 调整库存</p>
        </div>
      </div>

      <div class="bg-white rounded-xl p-6 shadow-sm mb-6">
        <div class="flex items-center justify-between mb-4">
          <h3 class="text-lg font-semibold text-slate-800 flex items-center gap-2">
            <svg class="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v4m0 0l-2-2m2 2l2-2M5 14a7 7 0 1014 0 7 7 0 00-14 0zM5 14H3m2 0H3m16 0h2"/></svg>
            智能派工建议
          </h3>
          <button onclick="navigateTo('production')" class="text-xs text-indigo-600 hover:underline">去派工 →</button>
        </div>
        ${dispatchItems}
      </div>

      <div class="grid grid-cols-1 gap-6">
        <div class="bg-white rounded-xl p-6 shadow-sm">
          <h3 class="text-lg font-semibold text-slate-800 mb-4">快捷操作</h3>
          <div class="grid grid-cols-2 gap-3">
            <button onclick="navigateTo('sales')" class="p-4 border border-slate-200 rounded-lg hover:bg-slate-50 text-left">
              <p class="font-medium text-slate-800">新建销售</p><p class="text-sm text-slate-500">创建销售订单</p>
            </button>
            <button onclick="navigateTo('purchase')" class="p-4 border border-slate-200 rounded-lg hover:bg-slate-50 text-left">
              <p class="font-medium text-slate-800">新建采购</p><p class="text-sm text-slate-500">创建采购订单</p>
            </button>
            <button onclick="showModal('addFinance')" class="p-4 border border-slate-200 rounded-lg hover:bg-slate-50 text-left">
              <p class="font-medium text-slate-800">财务记录</p><p class="text-sm text-slate-500">添加收支记录</p>
            </button>
            <button onclick="navigateTo('inventory')" class="p-4 border border-slate-200 rounded-lg hover:bg-slate-50 text-left">
              <p class="font-medium text-slate-800">库存管理</p><p class="text-sm text-slate-500">查看库存详情</p>
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
}

async function renderSales() {
  // // // // console.log('renderSales - salesSubTab:', salesSubTab);
  switch(salesSubTab) {
    case 'pending':
      await renderSalesOrdersPending();
      break;
    case 'list':
      await renderSalesOrdersList();
      break;
    case 'shipped':
      await renderShippedOrdersList();
      break;
    case 'sales-shipping':
      await renderShippingOrdersContent(document.getElementById('page-content'));
      break;
    case 'sales-order-shipping':
      await renderShippingOrdersContent(document.getElementById('page-content'));
      setTimeout(() => {
        if (typeof renderShippingByOrder === 'function') {
          renderShippingByOrder();
        }
      }, 100);
      break;
    case 'create':
    default:
      await renderSalesOrdersCreate();
      break;
  }
}

function switchSalesTab(tab) {
  salesSubTab = tab;
  saveSalesSubTab(tab);
  navigateTo('sales');
}

function renderSalesTabContent() {
  renderSalesOrdersList();
}

