function toggleOrderActions(orderId) {
  const extraActions = document.getElementById(`actions-${orderId}`) || document.getElementById(`extra-actions-${orderId}`);
  const toggleBtn = document.getElementById(`toggle-btn-${orderId}`);
  
  if (extraActions && toggleBtn) {
    const isHidden = extraActions.style.display === 'none' || extraActions.style.display === '';
    
    if (isHidden) {
      extraActions.style.display = 'flex';
      toggleBtn.textContent = '收缩';
    } else {
      extraActions.style.display = 'none';
      toggleBtn.textContent = '展示更多';
    }
  }
}

// 全局切换所有行的操作按钮
function toggleAllOrderActions() {
  const toggleBtn = document.getElementById('toggle-all-btn');
  if (!toggleBtn) return;
  
  const isExpanded = toggleBtn.textContent === '收缩';
  const allExtraActions = document.querySelectorAll('[id^="actions-"]');
  
  allExtraActions.forEach(el => {
    el.style.display = isExpanded ? 'none' : 'flex';
  });
  
  toggleBtn.textContent = isExpanded ? '展示更多' : '收缩';
}

