// 配货查询列表 - 筛选已配货订单
function filterAllocationList() {
  const startDate = document.getElementById('sales-list-date-start').value;
  const endDate = document.getElementById('sales-list-date-end').value;
  const orderNo = document.getElementById('sales-list-order-no').value.toLowerCase();
  const receiver = document.getElementById('sales-list-receiver').value.toLowerCase();
  const receiverPhone = document.getElementById('sales-list-receiver-phone').value;
  const productModel = document.getElementById('sales-list-product-model').value.toLowerCase();
  const customerId = document.getElementById('sales-list-customer').value;
  
  const tbody = document.getElementById('orders-allocation-tbody');
  if (!tbody) return;
  
  // 仅显示已配货状态的订单
  const allocatedOrders = data.salesOrders.filter(order => {
    return order.status === 'allocated' && isOrderVisibleToCurrentUser(order);
  });
  
  let filteredOrders = allocatedOrders.filter(order => {
    if (startDate) {
      const orderDate = order.orderDate || order.order_date || '';
      if (orderDate && orderDate < startDate) return false;
    }
    
    if (endDate) {
      const orderDate = order.orderDate || order.order_date || '';
      if (orderDate && orderDate > endDate) return false;
    }
    
    if (orderNo) {
      const orderNumber = (order.orderNo || order.orderNumber || order.order_number || '').toLowerCase();
      if (!orderNumber.includes(orderNo)) return false;
    }
    
    if (receiver) {
      const contactName = (order.contactName || order.contact || '').toLowerCase();
      if (!contactName.includes(receiver)) return false;
    }
    
    if (receiverPhone) {
      const phone = order.contactPhone || order.phone || '';
      if (!phone.includes(receiverPhone)) return false;
    }
    
    if (productModel) {
      const items = order.items || [];
      const hasMatchingModel = items.some(item => {
        const model = (item.productModel || item.model || '').toLowerCase();
        return model.includes(productModel);
      });
      if (!hasMatchingModel) return false;
    }
    
    if (customerId) {
      const id = String(order.customerId || order.customer_id || '');
      if (id !== customerId) return false;
    }
    
    return true;
  });
  
  if (filteredOrders.length === 0) {
    tbody.innerHTML = '<tr><td colspan="14" class="text-center py-12 text-slate-500">暂无已配货订单</td></tr>';
    return;
  }
  
  tbody.innerHTML = filteredOrders.map((order, index) => {
    const orderNo = order.orderNo || order.orderNumber || order.order_number || '-';
    const orderDate = order.orderDate || order.order_date || '-';
    const totalAmount = order.totalAmount || order.total_amount || 0;
    const receiver = order.contactName || order.contact || '-';
    const phone = order.contactPhone || order.phone || '-';
    const follower = order.follower || order.created_by || '-';
    const remark = order.remark || '-';
    // 配货日期（从订单跟踪记录中查找）
    let allocationDate = '-';
    if (data.orderTrackingRecords) {
      const allocRecord = data.orderTrackingRecords
        .filter(r => r.orderId === order.id && r.action === '配货')
        .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0];
      if (allocRecord) {
        allocationDate = formatDate(allocRecord.createdAt);
      }
    }
    return `
    <tr class="hover:bg-slate-50">
      <td class="px-2 py-2 text-center text-xs text-slate-600">${index + 1}</td>
      <td class="px-1 py-2 text-center whitespace-nowrap">
        <div class="flex flex-nowrap justify-center gap-1 items-center">
          <button onclick="viewOrderDetails('${order.id}')" class="text-xs text-blue-500 hover:text-blue-700 whitespace-nowrap">查看</button>
          <div id="actions-alloc-${order.id}" style="display:none" class="flex flex-nowrap justify-center gap-1 items-center">
            <span class="text-slate-400 text-xs">|</span>
            <button onclick="cancelAllocation('${order.id}')" class="text-xs text-red-500 hover:text-red-700 whitespace-nowrap">取消配货</button>
          </div>
        </div>
      </td>
      <td class="px-2 py-2 text-center text-xs font-medium text-slate-800">${orderNo}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${orderDate}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${getCustomerName(order.customerId || order.customer_id) || '未知'}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${receiver}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${phone}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${formatCurrency(totalAmount)}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${allocationDate}</td>
      <td class="px-2 py-2 text-center">
        <span class="px-2 py-1 rounded-full text-xs font-medium ${getStatusClass(order.status)}">${getStatusText(order.status)}</span>
      </td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${getDeliveryMethodText(order.deliveryMethod || order.delivery_method)}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${order.deliveryDate || order.delivery_date || '-'}</td>
      <td class="px-2 py-2 text-center text-xs text-slate-600">${follower}</td>
      <td class="px-2 py-2 text-left text-xs text-slate-600 whitespace-nowrap overflow-hidden text-ellipsis" title="${remark || ''}">${remark}</td>
    </tr>
  `;
  }).join('');
}

// 取消配货 - 恢复库存，订单回到 approved 状态
async function cancelAllocation(orderId) {
  showConfirmModal(
    '确认取消配货',
    '取消配货后，该订单将回到已审核状态，对应减掉的库存将恢复。是否继续？',
    async () => {
      try {
        const order = data.salesOrders.find(o => o.id === orderId || o.orderNo === orderId);
        if (!order) {
          showAlertModal('错误', '未找到订单');
          return;
        }
        
        // 恢复库存：把该订单对应减掉的库存加回去
        if (order.items && order.items.length > 0) {
          for (const item of order.items) {
            const inv = data.inventory.find(i => i.productId === item.productId || String(i.productId) === String(item.productId));
            if (inv) {
              inv.quantity = (Number(inv.quantity) || 0) + (Number(item.quantity) || 0);
            }
          }
        }
        
        // 订单状态从 allocated 回到 approved
        order.status = 'approved';
        
        // 同步到后端
        try {
          await fetch(`/api/sales-orders/${order.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(order)
          });
          // 同步库存
          if (data.inventory.length > 0) {
            for (const inv of data.inventory) {
              await fetch(`/api/inventory/${inv.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(inv)
              }).catch(() => {});
            }
          }
        } catch (e) {
          console.error('同步后端失败:', e);
        }
        
        // 添加跟踪记录
        try {
          await fetch(`/api/sales-orders/${order.id}/tracking`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: '取消配货',
              content: '取消配货，库存已恢复',
              operator: currentUser ? currentUser.name : '系统'
            })
          });
        } catch (e) {
          console.error('添加跟踪记录失败:', e);
        }
        
        showSuccessModal('取消配货成功');
        // 刷新配货查询列表
        setTimeout(() => {
          filterAllocationList();
        }, 1500);
      } catch (e) {
        console.error('取消配货失败:', e);
        showAlertModal('错误', '取消配货失败: ' + e.message);
      }
    }
  );
}

