function toggleDispatchProcess(btn, orderNo, itemIndex, processType) {
  const currentText = btn.textContent.trim();
  let newText = '';
  
  if (currentText === '1') {
    newText = '✕';
    btn.textContent = '✕';
    btn.classList.remove('bg-teal-500', 'text-white');
    btn.classList.add('bg-red-100', 'text-red-600');
  } else {
    newText = '1';
    btn.textContent = '1';
    btn.classList.remove('bg-red-100', 'text-red-600');
    btn.classList.add('bg-teal-500', 'text-white');
  }
  
  // 保存到数据对象和localStorage
  try {
    // 更新内存中的数据
    const order = data.schedulingOrders?.find(o => o.orderNo === orderNo);
    if (order && order.items && order.items[itemIndex]) {
      if (!order.items[itemIndex].processStatus) {
        order.items[itemIndex].processStatus = {};
      }
      order.items[itemIndex].processStatus[processType] = newText;
      
      // 保存到localStorage
      const storedData = localStorage.getItem('erpData');
      if (storedData) {
        const parsed = JSON.parse(storedData);
        const storedOrder = parsed.schedulingOrders?.find(o => o.orderNo === orderNo);
        if (storedOrder && storedOrder.items && storedOrder.items[itemIndex]) {
          if (!storedOrder.items[itemIndex].processStatus) {
            storedOrder.items[itemIndex].processStatus = {};
          }
          storedOrder.items[itemIndex].processStatus[processType] = newText;
        }
        localStorage.setItem('erpData', JSON.stringify(parsed));
      }
    }
  } catch (e) {
    console.error('保存工序状态失败:', e);
  }
}

