function saveDispatchDetail() {
  // 收集当前派工单详情页的数据
  const tableBody = document.getElementById('dispatch-table-body');
  if (!tableBody) {
    showAlertModal('提示', '未找到表格数据');
    return;
  }

  // 获取当前派工单的orderNo
  const orderNo = currentDispatchOrderNo;
  if (!orderNo) {
    showAlertModal('提示', '未找到派工单');
    return;
  }

  // 找到对应的派工单
  const order = data.schedulingOrders?.find(o => o.orderNo === orderNo);
  if (!order) {
    showAlertModal('提示', '未找到派工单');
    return;
  }

  // 收集确认人数据 - 根据标签页保存到不同字段
  const tab = currentDispatchTab;
  let fieldName = 'confirmPerson';
  if (tab === 'packaging') fieldName = 'packagingConfirmPerson';
  else if (tab === 'woodwork') fieldName = 'woodworkConfirmPerson';
  else if (tab === 'stockin') fieldName = 'stockinConfirmPerson';
  
  order.items.forEach((item, idx) => {
    // 根据工序获取对应的下拉框ID
    let selectId = `confirm-${tab}-${idx}`;
    if (tab === 'detail') {
      // 详情页使用原来的 confirm-person-{idx}
      selectId = `confirm-person-${idx}`;
    }
    const confirmSelect = document.getElementById(selectId);
    if (confirmSelect) {
      item[fieldName] = confirmSelect.value || '';
    }
  });

  // 保存到localStorage
  try {
    const storedData = localStorage.getItem('erpData');
    if (storedData) {
      const parsed = JSON.parse(storedData);
      // 更新派工单数据
      if (parsed.schedulingOrders) {
        const orderIndex = parsed.schedulingOrders.findIndex(o => o.orderNo === orderNo);
        if (orderIndex !== -1) {
          parsed.schedulingOrders[orderIndex] = order;
        } else {
          parsed.schedulingOrders.push(order);
        }
      } else {
        parsed.schedulingOrders = [order];
      }
      localStorage.setItem('erpData', JSON.stringify(parsed));
      data.schedulingOrders = parsed.schedulingOrders;
    }
  } catch (e) {
    console.error('保存失败:', e);
  }

  showSuccessModal('保存成功');
}

