function calculateCreateItemAmount(element) {
  const row = element.closest('tr');
  const qty = parseFloat(row.querySelector('.create-product-qty').value) || 0;
  const price = parseFloat(row.querySelector('.create-product-price').value) || 0;
  const discount = parseFloat(row.querySelector('.create-product-discount').value) || 100;
  const rebate = parseFloat(row.querySelector('.create-product-rebate').value) || 0;
  
  const amount = (qty * price * discount / 100) - rebate;
  row.querySelector('.create-product-amount').value = amount.toFixed(2);
  
  const editDiscount = document.getElementById('edit-discount');
  if (editDiscount) {
    calculateEditTotalAmount();
  } else {
    calculateCreateTotalAmount();
  }
}

function calculateCreateTotalAmount() {
  let total = 0;
  document.querySelectorAll('.create-product-amount').forEach(input => {
    total += parseFloat(input.value) || 0;
  });
  
  const discount = parseFloat(document.getElementById('create-discount').value) || 100;
  const rebate = parseFloat(document.getElementById('create-rebate').value) || 0;
  
  const discountedTotal = total * discount / 100 - rebate;
  
  document.getElementById('create-total-amount').value = discountedTotal.toFixed(2);
  
  const invoiceType = document.querySelector('input[name="create-invoice"]:checked').value;
  let taxAmount = '';
  if (invoiceType === '3percent') {
    taxAmount = (discountedTotal * 1.03).toFixed(2);
  } else if (invoiceType === '10percent') {
    taxAmount = (discountedTotal * 1.10).toFixed(2);
  }
  document.getElementById('create-total-tax').value = taxAmount;
  
  const settlementTotal = taxAmount || discountedTotal.toFixed(2);
  
  const paymentAmount = parseFloat(document.getElementById('create-payment-amount').value) || 0;
  const paymentDiscount = parseFloat(document.getElementById('create-payment-discount').value) || 0;
  const usePrepayment = parseFloat(document.getElementById('create-use-prepayment').value) || 0;
  
  const unpaidAmount = parseFloat(settlementTotal) - paymentAmount - paymentDiscount - usePrepayment;
  document.getElementById('create-unpaid-amount').value = unpaidAmount.toFixed(2);
}

