function editStockRecord(id) {
  const record = data.stockInRecords.find(r => r.id == id);
  if (!record) {
    showAlertModal('提示', '记录不存在');
    return;
  }

  const product = data.products.find(p => p.id == record.productId) || {};

  // 处理颜色选择
  let colorOptions = '';
  if (product.color) {
    const colors = product.color.split(',').map(c => c.trim()).filter(c => c);
    if (colors.length > 1) {
      colorOptions = colors.map(c => `<option value="${c}" ${record.color === c ? 'selected' : ''}>${c}</option>`).join('');
    } else {
      colorOptions = `<option value="${product.color}" ${record.color === product.color ? 'selected' : ''}>${product.color}</option>`;
    }
  }

  // 处理规格选择
  let specOptions = '';
  if (product.spec) {
    const specs = product.spec.split(',').map(s => s.trim()).filter(s => s);
    if (specs.length > 1) {
      specOptions = specs.map(s => `<option value="${s}" ${record.spec === s ? 'selected' : ''}>${s}</option>`).join('');
    } else {
      specOptions = `<option value="${product.spec}" ${record.spec === product.spec ? 'selected' : ''}>${product.spec}</option>`;
    }
  }

  // 处理台面颜色选择
  let tabletopColorOptions = '';
  const productTabletopColor = product.tabletopColor || product.tabletop_color || '';
  if (productTabletopColor) {
    const tabletopColors = productTabletopColor.split(',').map(t => t.trim()).filter(t => t);
    if (tabletopColors.length > 1) {
      tabletopColorOptions = tabletopColors.map(t => `<option value="${t}" ${record.tabletopColor === t ? 'selected' : ''}>${t}</option>`).join('');
    } else {
      tabletopColorOptions = `<option value="${productTabletopColor}" ${record.tabletopColor === productTabletopColor ? 'selected' : ''}>${productTabletopColor}</option>`;
    }
  }

  const modalHtml = `
    <div id="editStockModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div class="bg-white rounded-lg w-11/12 max-w-2xl max-h-[90vh] overflow-y-auto">
        <div class="flex items-center justify-between p-4 border-b border-slate-200">
          <h3 class="text-lg font-semibold text-slate-800">修改入库记录</h3>
          <button onclick="closeEditStockModal()" class="text-slate-400 hover:text-slate-600">
            <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
            </svg>
          </button>
        </div>
        <div class="p-4">
          <div class="grid grid-cols-2 gap-4">
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">库存编号</label>
              <input type="text" id="editStockNumber" value="${record.stockNumber || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">产品型号</label>
              <input type="text" value="${product.model || product.sku || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">产品名称</label>
              <input type="text" value="${product.name || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">入库数量</label>
              <input type="number" id="editQuantity" value="${record.quantity || 0}" class="w-full px-3 py-2 border border-slate-200 rounded-lg">
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">仓库</label>
              <select id="editWarehouse" class="w-full px-3 py-2 border border-slate-200 rounded-lg">
                ${(warehouseData || []).map(wh => `<option value="${wh.name}" ${wh.name == record.warehouse ? 'selected' : ''}>${wh.name}</option>`).join('')}
              </select>
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">仓位</label>
              <select id="editLocation" class="w-full px-3 py-2 border border-slate-200 rounded-lg">
                ${(locationData || []).filter(l => l.status === '启用').map(l => `<option value="${l.name}" ${l.name == record.location ? 'selected' : ''}>${l.name}</option>`).join('')}
              </select>
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">颜色</label>
              ${colorOptions ? `<select id="editColor" class="w-full px-3 py-2 border border-slate-200 rounded-lg">${colorOptions}</select>` : `<input type="text" id="editColor" value="${record.color || product.color || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>`}
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">规格</label>
              ${specOptions ? `<select id="editSpec" class="w-full px-3 py-2 border border-slate-200 rounded-lg">${specOptions}</select>` : `<input type="text" id="editSpec" value="${record.spec || product.spec || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>`}
            </div>
            <div>
              <label class="block text-sm font-medium text-slate-700 mb-1">台面颜色</label>
              ${tabletopColorOptions ? `<select id="editTabletopColor" class="w-full px-3 py-2 border border-slate-200 rounded-lg">${tabletopColorOptions}</select>` : `<input type="text" id="editTabletopColor" value="${record.tabletopColor || productTabletopColor || ''}" class="w-full px-3 py-2 border border-slate-200 rounded-lg" readonly>`}
            </div>
          </div>
        </div>
        <div class="flex justify-end gap-3 p-4 border-t border-slate-200">
          <button onclick="closeEditStockModal()" class="px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50">取消</button>
          <button onclick="saveEditStockRecord('${id}')" class="px-4 py-2 bg-cyan-500 text-white rounded-lg hover:bg-cyan-600">保存</button>
        </div>
      </div>
    </div>
  `;
  document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function closeEditStockModal() {
  const modal = document.getElementById('editStockModal');
  if (modal) modal.remove();
}

async function saveEditStockRecord(id) {
  // console.log('saveEditStockRecord called with id:', id);
  
  const quantity = parseInt(document.getElementById('editQuantity').value) || 0;
  const warehouse = document.getElementById('editWarehouse').value;
  const location = document.getElementById('editLocation').value;
  const color = document.getElementById('editColor')?.value || '';
  const spec = document.getElementById('editSpec')?.value || '';
  const tabletopColor = document.getElementById('editTabletopColor')?.value || '';

  // console.log('Form data:', { quantity, warehouse, location, color, spec, tabletopColor });

  const recordIndex = data.stockInRecords.findIndex(r => r.id == id);
  if (recordIndex === -1) {
    showAlertModal('提示', '记录不存在');
    return;
  }

  const record = data.stockInRecords[recordIndex];
  const oldQuantity = record.quantity;
  const product = data.products.find(p => p.id == record.productId);
  
  try {
    const response = await fetch(`/api/stock-in-records/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ quantity, warehouse, location, color, spec, tabletopColor })
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('API error:', response.status, errorText);
      throw new Error(`API request failed: ${response.status}`);
    }

    const result = await response.json();
    // console.log('Update successful, result:', result);

    data.stockInRecords[recordIndex].quantity = quantity;
    data.stockInRecords[recordIndex].warehouse = warehouse;
    data.stockInRecords[recordIndex].location = location;
    data.stockInRecords[recordIndex].color = color;
    data.stockInRecords[recordIndex].spec = spec;
    data.stockInRecords[recordIndex].tabletopColor = tabletopColor;

    if (product && product.stock !== undefined) {
      product.stock = (product.stock || 0) - oldQuantity + quantity;
    }
    // 同步更新 inventory
    const invItem = data.inventory.find(inv => String(inv.productId) === String(record.productId));
    if (invItem) {
      invItem.quantity = (Number(invItem.quantity) || 0) - oldQuantity + quantity;
    }

    saveDataToStorage();
    showSuccessModal('修改成功');
    closeEditStockModal();
    await fetchData();
    renderProductStockQuery();
  } catch (error) {
    console.error('Failed to update stock record:', error);
    showAlertModal('修改失败', error.message || '未知错误');
  }
}

