async function loadProductInventoryLocks(productId) {
  try {
    const response = await fetch(`/api/products/${productId}/inventory-locks`);
    const locks = await response.json();
    
    const content = document.getElementById('stockRecordLogContent');
    if (!content) return;
    
    if (locks.length === 0) {
      content.innerHTML = '<div class="text-center py-8 text-slate-500"><p>暂无锁定记录</p></div>';
      return;
    }
    
    content.innerHTML = `
      <div class="overflow-x-auto">
        <table class="w-full">
          <thead class="bg-slate-50">
            <tr class="text-xs">
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">序号</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">订单编号</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">客户名称</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">联系人</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">锁定数量</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">状态</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">下单日期</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">锁定时间</th>
              <th class="px-2 py-2 text-center font-medium text-slate-600 border-b border-slate-200">释放时间</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-slate-100">
            ${locks.map((lock, index) => {
              const statusText = lock.status === 'locked' ? '锁定中' : '已撤销';
              const statusClass = lock.status === 'locked' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700';
              return `
              <tr class="hover:bg-slate-50 ${lock.status !== 'locked' ? 'opacity-60' : ''}">
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${index + 1}</td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.orderNo || '-'}</td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.customerName || '-'}</td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.contact || '-'}</td>
                <td class="px-2 py-2 text-xs text-slate-600 font-medium text-center">${lock.lockedQuantity || 0}</td>
                <td class="px-2 py-2 text-center"><span class="px-2 py-1 rounded-full text-xs font-medium ${statusClass}">${statusText}</span></td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.orderDate ? formatDate(lock.orderDate) : '-'}</td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.lockedAt ? formatDateTime(lock.lockedAt) : lock.createdAt ? formatDateTime(lock.createdAt) : '-'}</td>
                <td class="px-2 py-2 text-xs text-slate-600 text-center">${lock.releasedAt ? formatDateTime(lock.releasedAt) : '-'}</td>
              </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  } catch (error) {
    console.error('加载产品锁定记录失败:', error);
    const content = document.getElementById('stockRecordLogContent');
    if (content) {
      content.innerHTML = '<div class="text-center py-8 text-red-500"><p>加载锁定记录失败</p></div>';
    }
  }
}

