function closeStockInModal() {
  const modal = document.getElementById('stockInModal');
  if (modal) {
    modal.remove();
  }
}

async function saveProductStockInFromModal() {
  const productId = document.getElementById('stockProduct').value;
  const quantity = parseInt(document.getElementById('stockQuantity').value);
  
  if (!productId) {
    showAlertModal('提示', '请选择产品');
    return;
  }
  
  if (!quantity || quantity <= 0) {
    showAlertModal('提示', '请输入入库数量');
    return;
  }
  
  const product = data.products.find(p => p.id == productId);
  if (product) {
    // 更新产品库存
    product.stock = (product.stock || 0) + quantity;
    
    // 更新库存记录表
    let inventory = data.inventory.find(inv => String(inv.productId) === String(productId));
    if (inventory) {
      inventory.quantity = (Number(inventory.quantity) || 0) + quantity;
    } else {
      // 如果库存记录不存在，创建新记录
      data.inventory.push({
        id: Date.now(),
        productId: productId,
        productName: product.name,
        model: product.model || product.sku || '',
        quantity: quantity,
        unit: product.unit || '',
        createdAt: new Date().toISOString()
      });
    }
    
    if (!data.stockRecords) {
      data.stockRecords = [];
    }
    
    if (!data.stockInRecords) {
      data.stockInRecords = [];
    }
    
    const stockMethod = document.getElementById('stockMethod').value;
    const warehouse = document.getElementById('stockWarehouse').value;
    const location = document.getElementById('stockLocation').value;
    const remark = document.getElementById('stockRemark').value;
    
    data.stockRecords.push({
      id: Date.now(),
      productId: productId,
      productName: product.name,
      model: product.model || product.sku || '',
      type: 'in',
      quantity: quantity,
      beforeStock: (product.stock || 0) - quantity,
      afterStock: product.stock,
      unit: product.unit || '',
      warehouse: warehouse,
      remark: remark,
      createdAt: new Date().toISOString()
    });
    
    data.stockInRecords.push({
      id: Date.now(),
      productId: productId,
      stockMethod: stockMethod,
      quantity: quantity,
      warehouse: warehouse,
      location: location,
      remark: remark,
      createdAt: new Date().toISOString()
    });
    
    // 同步到后端并重新获取数据
    try {
      const inventory = data.inventory.find(inv => String(inv.productId) === String(productId));
      if (inventory) {
        await fetch(`/api/inventory/${inventory.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(inventory)
        });
      }
      // 重新获取数据确保显示正确
      await fetchData();
    } catch (e) {
      console.error('同步库存失败:', e);
    }
    
    saveDataToStorage();
    showSuccessModal('入库成功');
    closeStockInModal();
    renderProductStockInList();
    // 刷新库存查询页面
    if (currentPage === 'inventory' && inventorySubTab === 'product-stock-query') {
      renderProductStockQuery();
    }
  }
}



