// 生成库存编号
function generateStockNumber() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');
  const random = String(Math.floor(Math.random() * 100)).padStart(2, '0');
  
  return `RK${year}${month}${day}${hours}${minutes}${seconds}${random}`;
}

// 获取当天的入库序
function getDailyStockNumber() {
  const today = new Date().toISOString().split('T')[0];
  const todayRecords = data.stockInRecords.filter(record => {
    return record.createdAt && record.createdAt.startsWith(today);
  });
  return todayRecords.length + 1;
}

async function saveAllStockIn() {
  if (stockInProducts.length === 0) {
    showAlertModal('提示', '请先添加产品');
    return;
  }
  
  const stockMethod = document.getElementById('stockMethod').value;
  const warehouse = document.getElementById('stockWarehouse').value;
  const remark = document.getElementById('stockRemark').value;
  
  if (!data.stockRecords) {
    data.stockRecords = [];
  }
  
  if (!data.stockInRecords) {
    data.stockInRecords = [];
  }
  
  // 获取当天入库起始序号
  const startDailySequence = getDailyStockNumber();
  
  let successCount = 0;
  
  for (let i = 0; i < stockInProducts.length; i++) {
    const item = stockInProducts[i];
    const product = data.products.find(p => p.id == item.productId);
    if (product && item.quantity > 0) {
      product.stock = (product.stock || 0) + item.quantity;
      
      // 使用用户选择的选项
      const displayColor = item.selectedColor || product.color || '';
      const displaySpec = item.selectedSpec || product.spec || '';
      const displayTabletopColor = item.selectedTabletopColor || product.tabletopColor || product.tabletop_color || '';
      
      // 生成库存编号 - 每个产品独立计算
      const stockNumber = `RK${new Date().getFullYear()}${String(new Date().getMonth() + 1).padStart(2, '0')}${String(new Date().getDate()).padStart(2, '0')}${String(startDailySequence + i).padStart(4, '0')}${String(successCount + 1).padStart(2, '0')}`;
      
      const stockRecord = {
        productId: item.productId,
        productName: product.name,
        model: product.model || product.sku || '',
        type: 'in',
        quantity: item.quantity,
        beforeStock: (product.stock || 0) - item.quantity,
        afterStock: product.stock,
        unit: product.unit || '',
        warehouse: warehouse,
        remark: remark,
        color: displayColor,
        spec: displaySpec,
        tabletopColor: displayTabletopColor
      };
      
      const stockInRecord = {
        productId: item.productId,
        stockMethod: stockMethod,
        quantity: item.quantity,
        warehouse: warehouse,
        location: item.location || '',
        remark: remark,
        color: displayColor,
        spec: displaySpec,
        tabletopColor: displayTabletopColor,
        stockNumber: stockNumber  // 添加库存编号
      };
      
      try {
        await fetch('/api/stock-records', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(stockRecord)
        });
        
        await fetch('/api/stock-in-records', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(stockInRecord)
        });
        
        data.stockRecords.push({ ...stockRecord, id: Date.now() + successCount, createdAt: new Date().toISOString() });
        data.stockInRecords.push({ ...stockInRecord, id: Date.now() + successCount + 1000, createdAt: new Date().toISOString() });
        
        successCount++;
      } catch (error) {
        console.error('Failed to save stock record:', error);
      }
    }
  }
  
  saveDataToStorage();
  showSuccessModal(`入库成功，共入库 ${successCount} 个产品`);
  
  stockInProducts = [];
  showStockInForm = false;
  // 入库成功后自动跳转到产品库存查询页面
  switchInventoryTab('product-stock-query');
}

