function updatePlanProductInfo(select) {
  const option = select.options[select.selectedIndex];
  if (option.value) {
    document.getElementById('plan-model').value = option.dataset.model || '';
    document.getElementById('plan-type').value = option.dataset.type || '';
    document.getElementById('plan-unit').value = option.dataset.unit || '';
  }
}

// 保存计划订单
async function savePlanOrder() {
  try {
    console.log('开始保存计划订单...');
    
    // 收集基本信息
    const orderNo = document.getElementById('plan-order-no').value;
    const customerSelect = document.getElementById('plan-customer');
    const customerId = customerSelect.value;
    const customerName = customerSelect.options[customerSelect.selectedIndex]?.textContent || '';
    const contactName = document.getElementById('plan-contact').value;
    const contactPhone = document.getElementById('plan-contact-phone').value;
    const startDate = document.getElementById('plan-start').value;
    const endDate = document.getElementById('plan-end').value;
    const remark = document.getElementById('plan-remark').value;
    
    console.log('基本信息:', { orderNo, customerId, customerName, contactName, contactPhone, startDate, endDate, remark });
    
    // 验证必填字段
    if (!orderNo) {
      showAlertModal('提示', '请填写计划单号');
      return;
    }
    
    if (!startDate) {
      showAlertModal('提示', '请选择开始日期');
      return;
    }
    
    if (!endDate) {
      showAlertModal('提示', '请选择结束日期');
      return;
    }
    
    // 收集产品明细
    const tbody = document.getElementById('plan-order-items');
    if (!tbody) {
      showAlertModal('提示', '请添加产品明细');
      return;
    }
    
    const rows = tbody.querySelectorAll('tr');
    const items = [];
    
    console.log('找到产品明细行数:', rows.length);
    
    rows.forEach((row, index) => {
      // 从隐藏字段获取产品ID
      const productIdInput = row.querySelector('.product-id-input');
      const productId = productIdInput ? productIdInput.value : '';
      
      // 从输入框获取型号文本
      const modelInput = row.querySelector('.product-model-input');
      const modelText = modelInput ? modelInput.value : '';
      
      // 如果没有选择产品，跳过这一行
      if (!productId && !modelText) {
        return;
      }
      
      // 获取产品图片
      let itemImage = '';
      if (productId && data.products) {
        const matchedProduct = data.products.find(p => p.id == productId || p.id === productId);
        if (matchedProduct && matchedProduct.image) {
          itemImage = matchedProduct.image;
        }
      }

      // 生成跟单号：年月+4位随机数字
      const now = new Date();
      const followUpNo = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${Math.floor(1000 + Math.random() * 9000)}`;
      
      // 从产品名称字段获取产品类型
      let productType = row.querySelector('td:nth-child(5) input')?.value || '';
      
      // 如果产品名称字段没有值，尝试从产品数据中获取
      if (!productType && productId && data.products) {
        const matchedProduct = data.products.find(p => p.id == productId || p.id === productId);
        if (matchedProduct) {
          productType = matchedProduct.type || matchedProduct.name || '';
        }
      }
      
      // 如果还是没有，尝试用型号获取
      if (!productType && modelText && data.products) {
        const matchedProduct = data.products.find(p => p.model === modelText || p.sku === modelText);
        if (matchedProduct) {
          productType = matchedProduct.type || matchedProduct.name || '';
        }
      }
      
      if (!productType) {
        productType = '成品';
      }

      // 收集每个字段的值
      const item = {
        orderIndex: index + 1,
        productId: productId,
        model: modelText || '',
        productName: row.querySelector('td:nth-child(5) input')?.value || '',
        color: row.querySelector('td:nth-child(6) input')?.value || '',
        spec: row.querySelector('td:nth-child(7) select')?.value || '',
        countertopColor: row.querySelector('td:nth-child(8) input')?.value || '',
        quantity: parseInt(row.querySelector('td:nth-child(9) input')?.value) || 1,
        unit: row.querySelector('td:nth-child(10) input')?.value || '',
        packageCount: parseInt(row.querySelector('td:nth-child(11) input')?.value) || 0,
        productionMethod: row.querySelector('td:nth-child(12) select')?.value || '生产',
        followUpMethod: row.querySelector('td:nth-child(13) select')?.value || '按个',
        productType: productType,
        remark: row.querySelector('td:nth-child(15) input')?.value || '',
        image: itemImage,
        followUpNo: followUpNo
      };
      
      items.push(item);
      console.log('产品明细:', item);
    });
    
    if (items.length === 0) {
      showAlertModal('提示', '请至少选择一个产品');
      return;
    }
    
    // 检查是编辑模式还是新建模式
    if (currentEditPlanOrderId) {
      // 编辑模式：调用后端 API 更新计划订单
      try {
        await fetch(`/api/plan-orders/${currentEditPlanOrderId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            customerId,
            customerName,
            contactName,
            contactPhone,
            startDate,
            endDate,
            remark,
            items
          })
        });
        console.log('计划订单已更新');
        showSuccessModal('计划订单更新成功');
      } catch (error) {
        showAlertModal('错误', '更新计划订单失败：' + error.message);
        return;
      }
      
      // 清除编辑状态
      currentEditPlanOrderId = null;
    } else {
      // 新建模式：调用后端 API 创建计划订单
      try {
        // 为每个产品创建计划订单
        for (const item of items) {
          await fetch('/api/plan-orders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              orderId: '',
              productId: item.productId,
              quantity: item.quantity,
              customerId,
              customerName,
              contactName,
              contactPhone,
              startDate,
              endDate,
              remark,
              color: item.color,
              spec: item.spec,
              countertopColor: item.countertopColor,
              model: item.model,
              productName: item.productName,
              productType: item.productType
            })
          });
        }
        console.log('计划订单已创建到后端');
        showSuccessModal('计划订单创建成功');
      } catch (error) {
        showAlertModal('错误', '创建计划订单失败：' + error.message);
        return;
      }
    }
    
    // 重新加载后端数据
    await fetchData();
    console.log('数据已同步');
    
    // 跳转到计划订单列表页面
    console.log('跳转到计划订单列表页面...');
    productionSubPage = 'list';
    saveProductionSubPage('list');
    renderProductionPlanOrders();
    
  } catch (error) {
    console.error('保存计划订单时出错:', error);
    showAlertModal('错误', '保存失败: ' + error.message);
  }
}

