async function deletePlanOrder(id) {
  showConfirmModal('删除计划订单', '确定要删除这个计划订单吗？', async function() {
    try {
      await fetch(`/api/plan-orders/${id}`, {
        method: 'DELETE'
      });
      await fetchData();
      renderProductionPlanOrders();
      showSuccessModal('计划订单删除成功');
    } catch (error) {
      showAlertModal('错误', '删除计划订单失败：' + error.message);
    }
  });
}

function toggleSelectAllScheduling(sourceCheckbox) {
  var isChecked = sourceCheckbox.checked;
  var tables = document.getElementsByTagName('table');
  for (var t = 0; t < tables.length; t++) {
    var table = tables[t];
    if (table.contains(sourceCheckbox)) {
      var checkboxes = table.querySelectorAll('tbody input[type="checkbox"]');
      for (var i = 0; i < checkboxes.length; i++) {
        checkboxes[i].checked = isChecked;
        if (window.toggleSelectRow) {
          window.toggleSelectRow(checkboxes[i]);
        }
      }
      break;
    }
  }
}

