function renderSettings() {
  if (settingsSubPage === 'params') {
    renderSettingsParams();
  } else if (settingsSubPage === 'company') {
    renderSettingsCompany();
  } else if (settingsSubPage === 'product') {
    renderSettingsProduct();
  } else if (settingsSubPage === 'dataSource') {
    renderSettingsDataSource();
  } else {
    renderSettingsParams();
  }
}

