let logisticsRegionData = [];
let overdueSettingData = [];

let salesSearchKeyword = '';

function initSalesData() {
  // 初始化收款类型数
  const savedPaymentType = localStorage.getItem(PAYMENT_TYPE_KEY);
  if (savedPaymentType) {
    paymentTypeData = JSON.parse(savedPaymentType);
  } else {
    paymentTypeData = [
      { id: 1, order: 1, displayValue: '现金', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '微信', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: '支付宝', attribute: '', isDefault: false },
      { id: 4, order: 4, displayValue: '银行转账', attribute: '', isDefault: false },
      { id: 5, order: 5, displayValue: '支票', attribute: '', isDefault: false }
    ];
    localStorage.setItem(PAYMENT_TYPE_KEY, JSON.stringify(paymentTypeData));
  }
  
  // 初始化提货方式数
  const savedPickupMethod = localStorage.getItem(PICKUP_METHOD_KEY);
  if (savedPickupMethod) {
    pickupMethodData = JSON.parse(savedPickupMethod);
  } else {
    pickupMethodData = [
      { id: 1, order: 1, displayValue: '自提', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '送货上门', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: '物流配送', attribute: '', isDefault: false }
    ];
    localStorage.setItem(PICKUP_METHOD_KEY, JSON.stringify(pickupMethodData));
  }
  
  // 初始化结算方式数
  const savedSettlementMethod = localStorage.getItem(SETTLEMENT_METHOD_KEY);
  if (savedSettlementMethod) {
    settlementMethodData = JSON.parse(savedSettlementMethod);
  } else {
    settlementMethodData = [
      { id: 1, order: 1, displayValue: '现结', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '月结30', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: '月结60', attribute: '', isDefault: false },
      { id: 4, order: 4, displayValue: '月结90', attribute: '', isDefault: false }
    ];
    localStorage.setItem(SETTLEMENT_METHOD_KEY, JSON.stringify(settlementMethodData));
  }
  
  // 初始化客户类型数
  const savedCustomerType = localStorage.getItem(CUSTOMER_TYPE_KEY);
  if (savedCustomerType) {
    customerTypeData = JSON.parse(savedCustomerType);
  } else {
    customerTypeData = [
      { id: 1, order: 1, displayValue: '零售客户', attribute: '零售客户', isDefault: true },
      { id: 2, order: 2, displayValue: '经销商', attribute: '经销商', isDefault: false },
      { id: 3, order: 3, displayValue: '电商', attribute: '电商', isDefault: false },
      { id: 4, order: 4, displayValue: '抖音线下', attribute: '经销商', isDefault: false }
    ];
    localStorage.setItem(CUSTOMER_TYPE_KEY, JSON.stringify(customerTypeData));
  }
  
  // 初始化客户区域数
  const savedCustomerRegion = localStorage.getItem(CUSTOMER_REGION_KEY);
  if (savedCustomerRegion) {
    customerRegionData = JSON.parse(savedCustomerRegion);
  } else {
    customerRegionData = [
      { id: 1, order: 1, displayValue: '华东', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '华南', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: '华北', attribute: '', isDefault: false },
      { id: 4, order: 4, displayValue: '华中', attribute: '', isDefault: false },
      { id: 5, order: 5, displayValue: '西南', attribute: '', isDefault: false },
      { id: 6, order: 6, displayValue: '西北', attribute: '', isDefault: false },
      { id: 7, order: 7, displayValue: '东北', attribute: '', isDefault: false }
    ];
    localStorage.setItem(CUSTOMER_REGION_KEY, JSON.stringify(customerRegionData));
  }
  
  // 初始化客户等级数
  const savedCustomerLevel = localStorage.getItem(CUSTOMER_LEVEL_KEY);
  if (savedCustomerLevel) {
    customerLevelData = JSON.parse(savedCustomerLevel);
  } else {
    customerLevelData = [
      { id: 1, order: 1, displayValue: 'A', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: 'B', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: 'C', attribute: '', isDefault: false },
      { id: 4, order: 4, displayValue: 'D', attribute: '', isDefault: false }
    ];
    localStorage.setItem(CUSTOMER_LEVEL_KEY, JSON.stringify(customerLevelData));
  }
  
  // 初始化物流区域数
  const savedLogisticsRegion = localStorage.getItem(LOGISTICS_REGION_KEY);
  if (savedLogisticsRegion) {
    logisticsRegionData = JSON.parse(savedLogisticsRegion);
  } else {
    logisticsRegionData = [
      { id: 1, order: 1, displayValue: '省内', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '省外', attribute: '', isDefault: false }
    ];
    localStorage.setItem(LOGISTICS_REGION_KEY, JSON.stringify(logisticsRegionData));
  }
  
  // 初始化超期设置数
  const savedOverdueSetting = localStorage.getItem(OVERDUE_SETTING_KEY);
  if (savedOverdueSetting) {
    overdueSettingData = JSON.parse(savedOverdueSetting);
  } else {
    overdueSettingData = [
      { id: 1, order: 1, displayValue: '30', attribute: '', isDefault: true },
      { id: 2, order: 2, displayValue: '60', attribute: '', isDefault: false },
      { id: 3, order: 3, displayValue: '90', attribute: '', isDefault: false }
    ];
    localStorage.setItem(OVERDUE_SETTING_KEY, JSON.stringify(overdueSettingData));
  }
}

function getCurrentSalesData() {
  switch (settingsSalesSubTab) {
    case 'paymentType': return paymentTypeData;
    case 'pickupMethod': return pickupMethodData;
    case 'settlementMethod': return settlementMethodData;
    case 'customerType': return customerTypeData;
    case 'customerRegion': return customerRegionData;
    case 'customerLevel': return customerLevelData;
    case 'logisticsRegion': return logisticsRegionData;
    case 'overdueSetting': return overdueSettingData;
    default: return paymentTypeData;
  }
}

function getCurrentSalesDataByKey(key) {
  switch (key) {
    case 'paymentType': return paymentTypeData;
    case 'pickupMethod': return pickupMethodData;
    case 'settlementMethod': return settlementMethodData;
    case 'customerType': return customerTypeData;
    case 'customerRegion': return customerRegionData;
    case 'customerLevel': return customerLevelData;
    case 'logisticsRegion': return logisticsRegionData;
    case 'overdueSetting': return overdueSettingData;
    default: return [];
  }
}

function saveSalesData(data) {
  switch (settingsSalesSubTab) {
    case 'paymentType':
      paymentTypeData = data;
      localStorage.setItem(PAYMENT_TYPE_KEY, JSON.stringify(data));
      break;
    case 'pickupMethod':
      pickupMethodData = data;
      localStorage.setItem(PICKUP_METHOD_KEY, JSON.stringify(data));
      break;
    case 'settlementMethod':
      settlementMethodData = data;
      localStorage.setItem(SETTLEMENT_METHOD_KEY, JSON.stringify(data));
      break;
    case 'customerType':
      customerTypeData = data;
      localStorage.setItem(CUSTOMER_TYPE_KEY, JSON.stringify(data));
      break;
    case 'customerRegion':
      customerRegionData = data;
      localStorage.setItem(CUSTOMER_REGION_KEY, JSON.stringify(data));
      break;
    case 'customerLevel':
      customerLevelData = data;
      localStorage.setItem(CUSTOMER_LEVEL_KEY, JSON.stringify(data));
      break;
    case 'logisticsRegion':
      logisticsRegionData = data;
      localStorage.setItem(LOGISTICS_REGION_KEY, JSON.stringify(data));
      break;
    case 'overdueSetting':
      overdueSettingData = data;
      localStorage.setItem(OVERDUE_SETTING_KEY, JSON.stringify(data));
      break;
  }
}

