let unitSearchKeyword = '';
function loadUnitData() {
  try {
    const saved = localStorage.getItem(UNIT_DATA_KEY);
    if (saved) {
      return JSON.parse(saved);
    }
  } catch (e) {
    console.error('Failed to load unit data:', e);
  }
  return [
    { id: 1, displayValue: '套', order: 1, isDefault: false },
    { id: 2, displayValue: '个', order: 2, isDefault: false },
    { id: 3, displayValue: '件', order: 3, isDefault: false },
    { id: 4, displayValue: '组', order: 4, isDefault: false },
    { id: 5, displayValue: '批', order: 5, isDefault: false }
  ];
}

function saveUnitData() {
  try {
    localStorage.setItem(UNIT_DATA_KEY, JSON.stringify(unitData));
  } catch (e) {
    console.error('Failed to save unit data:', e);
  }
}

