  document.getElementById('attr-type-filter').value = productAttributesFilter.type;
  document.getElementById('attr-name-filter').value = productAttributesFilter.name;
  
  document.getElementById('search-attr-btn').addEventListener('click', searchProductAttributes);
  document.getElementById('reset-attr-btn').addEventListener('click', resetProductAttributesFilter);
  document.getElementById('add-attr-btn').addEventListener('click', showAddProductAttributeModal);
