function searchProductAttributes() {
  productAttributesFilter.type = document.getElementById('attr-type-filter').value;
  productAttributesFilter.name = document.getElementById('attr-name-filter').value;
  renderSettingsProduct();
}

function resetProductAttributesFilter() {
  productAttributesFilter = { type: '', name: ''};
  renderSettingsProduct();
}

