function saveProductAttribute() {
  const newAttr = {
    id: Date.now(),
    type: document.getElementById('new-attr-type').value,
    name: document.getElementById('new-attr-name').value,
    productType: document.getElementById('new-attr-product-type').value,
    defaultValue: document.getElementById('new-attr-default').value,
    minValue: document.getElementById('new-attr-min').value,
    maxValue: document.getElementById('new-attr-max').value,
    decimalPlaces: document.getElementById('new-attr-decimal').value,
    modifier: document.getElementById('new-attr-modifier').value,
    dataSource: document.getElementById('new-attr-datasource').value
  };
  
  if (!newAttr.name.trim()) {
    showAlertModal('提示', '请输入属性名');
    return;
  }
  
  productAttributes.push(newAttr);
  saveProductAttributes();
  closeModal();
  renderSettingsProduct();
  showSuccessModal('保存成功');
}

function updateProductAttribute() {
  const id = parseInt(document.getElementById('edit-attr-id').value);
  const index = productAttributes.findIndex(a => a.id === id);
  
  if (index !== -1) {
    productAttributes[index] = {
      ...productAttributes[index],
      type: document.getElementById('edit-attr-type').value,
      name: document.getElementById('edit-attr-name').value,
      productType: document.getElementById('edit-attr-product-type').value,
      defaultValue: document.getElementById('edit-attr-default').value,
      minValue: document.getElementById('edit-attr-min').value,
      maxValue: document.getElementById('edit-attr-max').value,
      decimalPlaces: document.getElementById('edit-attr-decimal').value,
      modifier: document.getElementById('edit-attr-modifier').value,
      dataSource: document.getElementById('edit-attr-datasource').value
    };
    
    saveProductAttributes();
    closeModal();
    renderSettingsProduct();
    showSuccessModal('保存成功');
  }
}

function showDeleteProductAttributeConfirm(id) {
  showConfirmModal('删除产品属性', '确定要删除这个产品属性吗？', function() {
    productAttributes = productAttributes.filter(a => a.id !== id);
    saveProductAttributes();
    renderSettingsProduct();
    showSuccessModal('删除成功');
  });
}

