async function saveWarehouse() {
  const name = document.getElementById('warehouse-name').value;
  const isDefault = document.getElementById('warehouse-default').checked;
  const isActive = document.getElementById('warehouse-active').checked;
  
  if (!name.trim()) {
    showAlertModal('提示', '请输入仓库名');
    return;
  }
  
  try {
    // // // // console.log('Saving warehouse:', { name, isDefault, isActive });
    const response = await fetch('/api/warehouses', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        name: name,
        isDefault: isDefault,
        isActive: isActive,
        type: isDefault ? '主仓' : '分仓',
        manager: '-'
      })
    });
    
    // // // // console.log('Response status:', response.status);
    
    if (response.ok) {
      const result = await response.json();
      // // // // console.log('Save result:', result);
      showSuccessModal('保存成功');
      renderMaterialsWarehouseList();
    } else {
      const errorText = await response.text();
      console.error('Save failed:', errorText);
      showAlertModal('保存失败', errorText);
    }
  } catch (error) {
    console.error('Failed to save warehouse:', error);
    showAlertModal('保存失败', '保存失败，请检查控制台错误信息');
  }
}

async function fetchWarehouses() {
  try {
    const response = await fetch('/api/warehouses');
    warehouseData = await response.json();
  } catch (error) {
    console.error('Failed to fetch warehouses:', error);
    warehouseData = [];
  }
}

