async function handleSpecPriceSave(e) {
  e.preventDefault();
  
  const productSelect = document.getElementById('spec-price-product');
  const selectedOption = productSelect.options[productSelect.selectedIndex];
  
  const specPriceData = {
    productId: productSelect.value,
    productName: selectedOption.dataset.name || '',
    productModel: selectedOption.dataset.model || '',
    spec: document.getElementById('spec-price-spec').value,
    factoryPrice: parseFloat(document.getElementById('spec-price-factory').value) || 0,
    costPrice: parseFloat(document.getElementById('spec-price-cost').value) || 0,
    showroomPrice: parseFloat(document.getElementById('spec-price-showroom').value) || 0,
    remark: document.getElementById('spec-price-remark').value
  };
  
  if (!specPriceData.productId) {
    showAlertModal('提示', '请选择产品');
    return;
  }
  
  let result;
  if (currentEditSpecPrice) {
    result = await updateProductSpecPrice(currentEditSpecPrice.id, specPriceData);
  } else {
    result = await saveProductSpecPrice(specPriceData);
  }
  
  if (result) {
    closeModal();
    renderMaterialsProductSpecPrice();
  }
}

function confirmDeleteSpecPrice(id) {
  showConfirmModal('删除规格价格', '确定要删除这个规格价格吗？', function() {
    deleteProductSpecPrice(id).then(() => {
      renderMaterialsProductSpecPrice();
    });
  });
}

