function modifyCustomer(id) {
  const customer = data.customers.find(c => c.id == id);
  if (!customer) {
    showAlertModal('提示', '客户不存在');
    return;
  }
  
  materialsSubPage = 'customer-create';
  saveMaterialsSubPage('customer-create');
  renderMaterialsCustomerCreate();
  
  setTimeout(() => {
    document.getElementById('customer-name').value = customer.name || '';
    document.getElementById('customer-phone').value = customer.phone || '';
    document.getElementById('customer-address').value = customer.address || '';
    document.getElementById('customer-region').value = customer.region || '';
    document.getElementById('customer-type').value = customer.type || '';
    document.getElementById('customer-level').value = customer.level || '';
    document.getElementById('customer-email').value = customer.email || '';
    document.getElementById('customer-birthday').value = customer.birthday || '';
    document.getElementById('customer-pickup-method').value = customer.pickupMethod || '';
    document.getElementById('customer-logistics-name').value = customer.logisticsName || '';
    document.getElementById('customer-logistics-phone').value = customer.logisticsPhone || '';
    document.getElementById('customer-logistics-address').value = customer.logisticsAddress || '';
    document.getElementById('customer-province').value = customer.province || '';
    document.getElementById('customer-credit-limit').value = customer.creditLimit || '';
    document.getElementById('customer-develop-date').value = customer.developDate || '';
    document.getElementById('customer-discount').value = customer.discount || '';
    document.getElementById('customer-brand').value = customer.brand || '';
    document.getElementById('customer-source').value = customer.source || '';
    document.getElementById('customer-rebate-rate').value = customer.rebateRate || '';
    document.getElementById('customer-contact').value = customer.contact || '';
    document.getElementById('customer-salesman').value = customer.salesman || '';
    document.getElementById('customer-maintainer').value = customer.maintainer || '';
    document.getElementById('customer-follower').value = customer.follower || '';
    document.getElementById('customer-regional-manager').value = customer.regionalManager || '';
    document.getElementById('customer-salesman-rate').value = customer.salesmanRate || '';
    document.getElementById('customer-maintainer-rate').value = customer.maintainerRate || '';
    document.getElementById('customer-follower-rate').value = customer.followerRate || '';
    document.getElementById('customer-regional-manager-rate').value = customer.regionalManagerRate || '';
    document.getElementById('customer-deposit-rate').value = customer.depositRate || '';
    document.getElementById('customer-account').value = customer.account || '';
    document.getElementById('customer-settlement-method').value = customer.settlementMethod || '';
    document.getElementById('customer-created-date').value = customer.createdDate || '';
    document.getElementById('customer-preferential-policy').value = customer.preferentialPolicy || '';
    document.getElementById('customer-remark').value = customer.remark || '';
    
    const saveBtn = document.querySelector('button:contains("保存客户")');
    if (saveBtn) {
      saveBtn.setAttribute('onclick', `saveModifiedCustomer(${id})`);
      saveBtn.textContent = '保存修改';
    }
  }, 100);
}

async function deleteCustomer(id) {
  showConfirmModal('删除客户', '确定要删除这个客户吗？', async function() {
    try {
      const response = await fetch(`/api/customers/${id}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' }
      });
      
      const result = await response.json();
      
      if (result.success) {
        data.customers = data.customers.filter(c => c.id != id);
        saveCustomers();
        renderMaterialsCustomerList();
        showSuccessModal('删除成功');
      } else {
        showAlertModal('删除失败', result.message || '未知错误');
      }
    } catch (error) {
      console.error('删除客户失败:', error);
      showAlertModal('删除失败', error.message);
    }
  });
}

window.deleteCustomer = deleteCustomer;

