let currentEditingWarehouseIndex = null;

function showWarehouseEditModal(index) {
  currentEditingWarehouseIndex = index;
  const warehouse = warehouseData[index];
  
  const managerUsers = data.users.filter(u => 
    u.role && (u.role.includes('仓管') || u.role.includes('管理') || u.role.includes('管理员'))
  );
  
  const modal = document.createElement('div');
  modal.id = 'modal';
  modal.className = 'fixed inset-0 bg-black/50 flex items-center justify-center z-50';
  modal.innerHTML = `
    <div class="bg-white rounded-xl p-6 w-full max-w-md mx-4 shadow-xl">
      <div class="flex items-center justify-between mb-4">
        <h3 class="text-lg font-semibold text-slate-800">编辑信息</h3>
        <button onclick="closeModal()" class="text-slate-400 hover:text-slate-600">&times;</button>
      </div>
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium text-slate-700 mb-2">名称</label>
          <input type="text" id="edit-warehouse-name" class="w-full px-4 py-2 border border-slate-200 rounded-lg" value="${warehouse.name || ''}">
        </div>
        <div>
          <label class="block text-sm font-medium text-slate-700 mb-2">负责人</label>
          <select id="edit-warehouse-manager" class="w-full px-4 py-2 border border-slate-200 rounded-lg">
            <option value="">请选择负责人</option>
            ${managerUsers.map(u => `<option value="${u.name}" ${warehouse.manager === u.name ? 'selected' : ''}>${u.name}</option>`).join('')}
          </select>
        </div>
      </div>
      <div class="flex justify-end gap-3 mt-6">
        <button onclick="closeModal()" class="px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50">取消</button>
        <button onclick="saveWarehouseEdit()" class="px-4 py-2 bg-teal-500 text-white rounded-lg hover:bg-teal-600">保存</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
}

async function saveWarehouseEdit() {
  if (currentEditingWarehouseIndex === null) return;
  
  const warehouse = warehouseData[currentEditingWarehouseIndex];
  const warehouseId = warehouse.id;
  const name = document.getElementById('edit-warehouse-name').value.trim();
  const manager = document.getElementById('edit-warehouse-manager').value.trim();
  
  if (!name) {
    showAlertModal('提示', '请输入仓库名称');
    return;
  }
  
  try {
    const response = await fetch(`/api/warehouses/${warehouseId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, manager })
    });
    
    if (response.ok) {
      closeModal();
      showSuccessModal('修改成功');
      await fetchWarehouses();
      renderMaterialsWarehouseList();
    } else {
      showAlertModal('提示', '修改失败，请重试');
    }
  } catch (error) {
    console.error('Failed to update warehouse:', error);
    showAlertModal('提示', '修改失败，请重试');
  }
}

let currentDeletingWarehouseIndex = null;

function showWarehouseDeleteConfirm(index) {
  currentDeletingWarehouseIndex = index;
  
  const existingModal = document.getElementById('delete-confirm-modal');
  if (existingModal) {
    existingModal.remove();
  }
  
  const modal = document.createElement('div');
  modal.id = 'delete-confirm-modal';
  modal.className = 'fixed inset-0 bg-black/50 flex items-center justify-center z-50';
  modal.innerHTML = `
    <div class="bg-white rounded-xl p-6 w-full max-w-sm mx-4 shadow-xl">
      <div class="text-center">
        <div class="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
          <svg class="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/>
          </svg>
        </div>
        <h3 class="text-lg font-semibold text-slate-800 mb-2">确认删除</h3>
        <p class="text-slate-600 mb-6">确定要删除这条记录吗？此操作无法撤销</p>
        <div class="flex justify-center gap-3">
          <button onclick="document.getElementById('delete-confirm-modal').remove()" class="px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50">取消</button>
          <button onclick="confirmWarehouseDelete()" class="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600">确认删除</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
}

async function confirmWarehouseDelete() {
  if (currentDeletingWarehouseIndex === null) return;
  
  const warehouse = warehouseData[currentDeletingWarehouseIndex];
  const warehouseId = warehouse.id;
  
  try {
    const response = await fetch(`/api/warehouses/${warehouseId}`, {
      method: 'DELETE'
    });
    
    document.getElementById('delete-confirm-modal').remove();
    
    if (response.ok) {
      showSuccessModal('删除成功');
      await fetchWarehouses();
      renderMaterialsWarehouseList();
    } else {
      showAlertModal('提示', '删除失败，请重试');
    }
  } catch (error) {
    console.error('Failed to delete warehouse:', error);
    showAlertModal('提示', '删除失败，请重试');
  }
}

function closeModal() {
  const modal = document.getElementById('modal');
  if (modal) {
    modal.remove();
  }
}

function openModal() {
  const modal = document.getElementById('modal');
  const modalContent = document.getElementById('modal-content');
  if (modal && modalContent) {
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    modal.style.display = 'flex';
    modal.style.alignItems = 'center';
    modal.style.justifyContent = 'center';
    modal.style.zIndex = '100';
    modalContent.style.margin = 'auto';
    modalContent.style.maxWidth = '50vw';
    modalContent.style.maxHeight = '85vh';
  }
}

function saveEdit() {
  closeModal();
  showSuccessModal('编辑成功');
}

async function confirmDelete() {
  const modal = document.getElementById('delete-confirm-modal');
  if (modal) {
    modal.remove();
  }
  
  if (warehouseData.length > 0) {
    const warehouseId = warehouseData[0].id;
    try {
      const response = await fetch(`/api/warehouses/${warehouseId}`, {
        method: 'DELETE'
      });
      
      if (response.ok) {
        setTimeout(() => showSuccessModal('删除成功'), 100);
      } else {
        setTimeout(() => showAlertModal('提示', '删除失败，请重试'), 100);
      }
    } catch (error) {
      console.error('Failed to delete warehouse:', error);
      setTimeout(() => showAlertModal('提示', '删除失败，请重试'), 100);
    }
  }
  
  renderMaterialsWarehouseList();
}

let currentUser = {
  name: '管理',
  email: 'admin@example.com',
  avatar: 'A'
};

function loadUserInfo() {
  const sessionUser = sessionStorage.getItem(CURRENT_USER_KEY);
  if (sessionUser) {
    currentUser = JSON.parse(sessionUser);
  } else {
    const saved = localStorage.getItem('userInfo');
    if (saved) {
      currentUser = JSON.parse(saved);
    }
  }
  updateUserInfoDisplay();
}

function updateUserInfoDisplay() {
  const nameEl = document.getElementById('user-name');
  const emailEl = document.getElementById('user-email');
  const avatarEl = document.getElementById('user-avatar');
  
  if (nameEl) nameEl.textContent = currentUser.name;
  if (emailEl) emailEl.textContent = currentUser.email;
  if (avatarEl) avatarEl.textContent = currentUser.avatar || currentUser.name.charAt(0);
}

