async function saveUserInfo() {
  const name = document.getElementById('edit-user-name').value;
  const email = document.getElementById('edit-user-email').value;
  const avatar = document.getElementById('edit-user-avatar').value;
  const oldPassword = document.getElementById('edit-user-old-password').value;
  const newPassword = document.getElementById('edit-user-new-password').value;
  const confirmPassword = document.getElementById('edit-user-confirm-password').value;
  
  if (!name.trim()) {
    showAlertModal('提示', '请输入用户名');
    return;
  }
  
  if (!email.trim()) {
    showAlertModal('提示', '请输入邮箱');
    return;
  }
  
  if (newPassword || oldPassword) {
    if (!oldPassword) {
      showAlertModal('提示', '请输入原密码');
      return;
    }
    if (!newPassword) {
      showAlertModal('提示', '请输入新密码');
      return;
    }
    if (newPassword !== confirmPassword) {
      showAlertModal('提示', '两次输入的新密码不一致');
      return;
    }
    if (newPassword.length < 6) {
      showAlertModal('提示', '新密码长度不能少于6位');
      return;
    }
  }
  
  const updateData = {
    name: name.trim(),
    email: email.trim(),
    avatar: avatar.trim() || name.charAt(0)
  };
  
  if (newPassword) {
    updateData.oldPassword = oldPassword;
    updateData.newPassword = newPassword;
  }
  
  try {
    const response = await fetch('/api/users/me', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updateData)
    });
    
    const result = await response.json();
    
    if (result.success) {
      currentUser = { ...currentUser, ...result.user };
      saveLogin(sessionStorage.getItem(LOGIN_TOKEN_KEY), currentUser);
      updateUserInfoDisplay();
      
      const modal = document.getElementById('user-info-modal');
      if (modal) {
        modal.remove();
      }
      
      showSuccessModal('保存成功');
    } else {
      showAlertModal('提示', result.message || '保存失败');
    }
  } catch (e) {
    console.error('保存用户信息失败:', e);
    showAlertModal('提示', '保存失败: ' + e.message);
  }
}

function loadCurrentPage() {
  try {
    const saved = localStorage.getItem(CURRENT_PAGE_KEY);
    return saved || 'dashboard';
  } catch (e) {
    console.error('Failed to load current page:', e);
    return 'dashboard';
  }
}

async function navigateTo(page) {
  // // // // console.log('navigateTo called with:', page);
  currentPage = page;
  saveCurrentPage(page);
  highlightSidebar(page);
  
  // 如果是生产管理页面，保存子页面状态
  if (page === 'production') {
    saveProductionSubPage(productionSubPage);
  }
  
  // 如果是销售相关页面，重新获取数据以确保产品列表是最新的
  if (page === 'sales') {
    await fetchData();
  }
  
  renderPage(page);
}

document.addEventListener('DOMContentLoaded', async () => {
  // 检查登录状态
  if (!isLoggedIn()) {
    renderLogin();
    return;
  }
  
  // // // // console.log('DOMContentLoaded event fired');
  initProductTypeData();
  await fetchData();
  updateSystemTitle();
  loadUserInfo();
  applyRoleGating();
  loadFooterInfo();
  loadLocationData();
  fetchNotifications();
  const savedPage = loadCurrentPage();
  const savedSubPage = loadMaterialsSubPage();
  _materialsSubPage = savedSubPage;
  // 恢复生产管理子页面状态
  productionSubPage = loadProductionSubPage();
  // // // // console.log('About to render page:', savedPage, 'with subpage:', savedSubPage, 'productionSubPage:', productionSubPage);
  renderPage(savedPage);
  startAutoRefresh();
});

// ===== 多用户自动刷新：定期静默同步最新数据并重渲染当前页 =====
let _autoRefreshDataSignals = {}; // 各集合长度作为数据变化指纹
let _autoRefreshTimer = null;
function dataSignals(d) {
  const s = d || data;
  return [
    (s.salesOrders || []).length,
    (s.planOrders || []).length,
    (s.processes || []).length,
    (s.inventory || []).length,
    (s.products || []).length,
    (s.suppliers || []).length
  ].join(',');
}
function startAutoRefresh() {
  if (_autoRefreshTimer) clearInterval(_autoRefreshTimer);
  _autoRefreshDataSignals = dataSignals();
  _autoRefreshTimer = setInterval(async () => {
    try {
      const page = loadCurrentPage() || currentPage;
      // 不在登录/列表页则跳过；dashboard / 各列表页支持静默刷新
      if (!page) return;
      const before = dataSignals();
      await fetchData();
      const after = dataSignals();
      if (before !== after) {
        // 数据有变化（其他用户操作了），重新渲染当前页
        renderPage(page);
      }
    } catch (e) {
      console.error('自动刷新失败:', e);
    }
  }, 30000);
}

// 全局变量存储图片数据
let currentProductImage = '';
// 当前正在编辑的产品ID
let currentEditingProductId = null;

function previewProductImage(input) {
  if (input.files && input.files[0]) {
    const file = input.files[0];
    
    // 检查文件大(5MB)
    if (file.size > 5 * 1024 * 1024) {
      showAlertModal('提示', '图片大小不能超过 5MB');
      return;
    }
    
    const reader = new FileReader();
    reader.onload = function(e) {
      currentProductImage = e.target.result;
      const preview = document.getElementById('product-image-preview');
      preview.innerHTML = `<img src="${e.target.result}" class="w-full h-full object-cover" />`;
    };
    reader.readAsDataURL(file);
  }
}

