async function updateProduct() {
  const model = document.getElementById('product-model').value;
  const type = document.getElementById('product-type').value;
  const productionMethod = document.getElementById('production-method').value;
  const color = document.getElementById('product-color').value;
  const spec = document.getElementById('product-spec').value;
  const tabletopColor = document.getElementById('product-tabletop-color').value;
  const unit = document.getElementById('product-unit').value;
  const packageCount = document.getElementById('package-count').value;
  const supplier = document.getElementById('product-supplier').value;
  const factoryPrice = document.getElementById('factory-price').value;
  const costPrice = document.getElementById('cost-price').value;
  const showroomPrice = document.getElementById('showroom-price').value;
  const packageInfo = document.getElementById('product-package').value;
  const carpentry = document.getElementById('product-carpentry').value;
  const warehouse = document.getElementById('product-warehouse').value;
  const remark = document.getElementById('product-remark').value;
  
  // // // // console.log('updateProduct called, currentEditingProductId:', currentEditingProductId);
  // // // // console.log('data.products length:', data.products.length);
  // // // // console.log('data.products:', JSON.stringify(data.products));
  
  const productIndex = data.products.findIndex(p => p.id == currentEditingProductId);
  // // // // console.log('productIndex:', productIndex);
  
  if (productIndex === -1) {
    showAlertModal('提示', `未找到该产品，ID: ${currentEditingProductId}`);
    return;
  }
  
  const updatedProduct = {
    ...data.products[productIndex],
    model: model.trim(),
    name: model.trim(),
    type: type,
    productionMethod: productionMethod,
    color: color,
    spec: spec,
    tabletopColor: tabletopColor,
    unit: unit,
    packageCount: parseInt(packageCount) || 0,
    supplier: supplier,
    factoryPrice: parseFloat(factoryPrice) || 0,
    costPrice: parseFloat(costPrice) || 0,
    showroomPrice: parseFloat(showroomPrice) || 0,
    packageInfo: packageInfo,
    carpentry: carpentry,
    warehouse: warehouse,
    image: currentProductImage || data.products[productIndex].image,
    remark: remark.trim(),
    updatedAt: new Date().toISOString()
  };
  
  // 保存到服务器
  try {
    const url = `/api/products/${currentEditingProductId}`;
    // // // // console.log('Sending PUT request to:', url);
    // // // // console.log('Request body:', JSON.stringify(updatedProduct));
    
    const response = await fetch(url, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(updatedProduct)
    });
    
    // // // // console.log('Response status:', response.status, response.statusText);
    
    if (response.ok) {
      const savedProduct = await response.json();
      // // // // console.log('Server response:', savedProduct);
      
      data.products[productIndex] = savedProduct;
      saveDataToStorage();
      saveProductAttributes();
      saveDataSources();
      
      showSuccessModal('产品更新成功');
      cancelProductCreation();
    } else {
      const errorText = await response.text();
      console.error('Server error:', errorText);
      showAlertModal('更新失败', `服务器返回: ${response.status} - ${errorText}`);
    }
  } catch (error) {
    console.error('更新产品时发生错', error);
    showAlertModal('更新失败', '请检查网络连接或重试');
  }
}

async function saveProduct() {
  const model = document.getElementById('product-model').value;
  const type = document.getElementById('product-type').value;
  const productionMethod = document.getElementById('production-method').value;
  const color = document.getElementById('product-color').value;
  const spec = document.getElementById('product-spec').value;
  const tabletopColor = document.getElementById('product-tabletop-color').value;
const unit = document.getElementById('product-unit').value;
  const packageCount = document.getElementById('package-count').value;
  const supplier = document.getElementById('product-supplier').value;
  const factoryPrice = document.getElementById('factory-price').value;
  const costPrice = document.getElementById('cost-price').value;
  const showroomPrice = document.getElementById('showroom-price').value;
  const packageInfo = document.getElementById('product-package').value;
  const carpentry = document.getElementById('product-carpentry').value;
  const warehouse = document.getElementById('product-warehouse').value;
  const remark = document.getElementById('product-remark').value;
  
  const newProduct = {
    id: Date.now(),
    model: model.trim(),
    name: model.trim(),
    type: type,
    productionMethod: productionMethod,
    color: color,
    spec: spec,
    tabletopColor: tabletopColor,
unit: unit,
    packageCount: parseInt(packageCount) || 0,
    supplier: supplier,
    factoryPrice: parseFloat(factoryPrice) || 0,
    costPrice: parseFloat(costPrice) || 0,
    showroomPrice: parseFloat(showroomPrice) || 0,
    packageInfo: packageInfo,
    carpentry: carpentry,
    warehouse: warehouse,
    image: currentProductImage,
    remark: remark.trim(),
    createdAt: new Date().toISOString()
  };
  
  // // // // console.log('保存产品 - 完整数据:', newProduct);
  
  // 保存到服务器
  try {
    const response = await fetch('/api/products', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(newProduct)
    });
    
    if (response.ok) {
      const savedProduct = await response.json();
      data.products.push(savedProduct);
      saveDataToStorage();
      saveProductAttributes();
      saveDataSources();
      
      // 保存规格价格
      if (quickSpecPrices.length > 0) {
        for (const item of quickSpecPrices) {
          const specPriceData = {
            productId: savedProduct.id,
            productName: model.trim(),
            productModel: model.trim(),
            spec: item.spec,
            factoryPrice: item.factoryPrice || 0,
            costPrice: item.costPrice || 0,
            showroomPrice: item.showroomPrice || 0,
            remark: ''
          };
          await saveProductSpecPrice(specPriceData);
        }
      }
      
      // 清除数据
      currentProductImage = '';
      quickSpecPrices = [];
      
      showSuccessModal('产品保存成功');
      materialsSubPage = 'product-list';
      renderMaterialsProductList();
    } else {
      showAlertModal('保存失败', '请重试');
    }
  } catch (error) {
    console.error('保存产品时发生错', error);
    showAlertModal('保存失败', '请重试');
  }
}

async function saveDataToStorage() {
  try {
    localStorage.setItem('erpData', JSON.stringify(data));
    localStorage.setItem('warehouseData', JSON.stringify(warehouseData));
  } catch (e) {
    console.error('Failed to save data to storage:', e);
  }
}

async function syncSalesOrderToBackend(order) {
  try {
    const response = await fetch(`/api/sales-orders/${order.id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(order)
    });
    const result = await response.json();
    if (!result.success) {
      console.error('Failed to sync sales order:', result.message);
    }
  } catch (e) {
    console.error('Error syncing sales order:', e);
  }
}

async function deleteProduct(productId) {
  // // // // console.log('尝试删除产品，productId:', productId);
  showConfirmModal('删除产品', '确定要删除这个产品吗？', async function() {
    try {
      // // // // console.log('发送删除请求到 /api/products/' + productId);
      const response = await fetch(`/api/products/${productId}`, {
        method: 'DELETE'
      });
      // // // // console.log('响应', response.status, response.ok);
      
      if (response.ok) {
        const result = await response.json();
        // // // // console.log('删除成功:', result);
        data.products = data.products.filter(p => p.id !== productId);
        saveDataToStorage();
        renderMaterialsProductList();
        showSuccessModal('产品删除成功');
      } else {
        console.error('删除失败，响应状', response.status);
        showAlertModal('删除失败', '请重试');
      }
    } catch (error) {
      console.error('删除产品时发生错', error);
      showAlertModal('删除失败', '请重试');
    }
  });
}
