// 状态相关函数
function getStatusClass(status) {
  const map = { 
    pending: 'status-pending', 
    approved: 'bg-teal-100 text-teal-700', 
    allocated: 'bg-cyan-100 text-cyan-700',
    in_production: 'bg-orange-100 text-orange-700',
    in_progress: 'status-in-progress', 
    shipped: 'bg-blue-100 text-blue-700', 
    completed: 'status-completed', 
    cancelled: 'status-cancelled' 
  };
  return map[status] || 'status-pending';
}

function getStatusText(status) {
  const map = { 
    pending: '待审核', 
    approved: '已审核', 
    allocated: '已配货',
    in_production: '生产中',
    in_progress: '进行中', 
    shipped: '已发货', 
    completed: '已完成', 
    cancelled: '已作废' 
  };
  return map[status] || status;
}

// 其他可能缺失的函数
function getDeliveryMethodText(method) {
  if (!method) return '-';
  const deliveryMethods = dataSources['提货方式'] || [];
  const found = deliveryMethods.find(item => item.displayValue === method);
  if (found) {
    return found.displayValue;
  }
  return method;
}

function getProductName(id) {
  const product = data.products.find(p => p.id === id);
  return product ? product.name : '未知';
}

function getCustomerName(id) {
  const customer = data.customers.find(c => String(c.id) === String(id));
  return customer ? customer.name : '未知';
}

function getSupplierName(id) {
  const supplier = data.suppliers.find(s => s.id === id);
  return supplier ? supplier.name : '未知';
}

